IG$.prepareCustomMenu = function(record, btype) {
	var me = this,
		instance = me.instance,
		menu = me.customMenu,
		data = record.data,
		typename = data.type.toLowerCase(),
		itemname = data.locale_name || data.name,
		itemaddr = data.nodepath || "/",
		itemuid = data.uid,
		itemtype = data.type,
		writable = (data.writable || data.manage) ? true : false,
		manageable = (data.manage) ? true : false,
		issubcube = data.issubcube,
		isrfolder = data.isrfolder,
		isbo = data.isbo,
		isdatasource = me.isdatasource,
		wobj,
		topPanel = instance.mainPanel,
		mvisible = false,
		is_priv = data.is_priv,
		is_dept = data.is_dept,
		meta_type = me.meta_type;
		
	menu.removeAll();
	
	switch (typename)
	{
	case "root":
		wobj = {
			text: IRm$.r1("L_WORKSPACE"),
			hidden: ig$.features["ig_n_cw"] !== false,
			handler: function() {
				this._createMetaObject("Folder", itemuid, itemaddr, record);
			},
			scope: this
		};
		
		if (!wobj.hidden)
		{
			menu.add(wobj);
			mvisible = true;
		}
		break;
	case "folder":
	case "rfolder":
	case "javapackage":
		if (typename == "javapackage")
		{
			isbo = typename;
		}
		var smenu;
		if (isbo)
		{
			smenu = [
				{
					text: IRm$.r1("B_FOLDER"),
					hidden: ig$.features["ig_n_f_f"] !== false,
					handler: function() {
						this._createMetaObject("Folder", itemuid, itemaddr, record);
					},
					scope: this
				},
				{
					text: IRm$.r1("B_JAVA_CLASS"),
					hidden: ig$.features["ig_n_jc"] !== false,
					handler: function() {
						this._createMetaObject("JavaClass", itemuid, itemaddr, record);
					},
					scope: this
				}
			];
		}
		else if (btype == "codemap")
		{
			smenu = [
				 {
					 text: IRm$.r1("B_FOLDER"),
					 hidden: ig$.features["ig_n_f_f"] !== false,
					 handler: function() {
						 this._createMetaObject("Folder", itemuid, itemaddr, record);
					 },
					 scope: this
				 },
				 {
					 text: IRm$.r1("L_CODEMAPPING"),
					 hidden: ig$.features["ig_n_lk"] !== false,
					 handler: function() {
					 	this._createMetaObject("CodeMap", itemuid, itemaddr, record);
					 },
					 scope: this
				 }
			 ];
		}
		else if (btype == "NLP")
		{
			smenu = [
				 {
					 text: IRm$.r1("B_FOLDER"),
					 hidden: ig$.features["ig_n_f_f"] !== false,
					 handler: function() {
						 this._createMetaObject("Folder", itemuid, itemaddr, record);
					 },
					 scope: this
				 },
				 {
					 text: IRm$.r1("L_NLP"),
					 handler: function() {
					 	this._createMetaObject("NLP", itemuid, itemaddr, record);
					 },
					 scope: this
				 }
			 ];
		}
		else if (isdatasource)
		{
			smenu = [
				{
					text: IRm$.r1("L_IMP_TABLES"),
					handler: function() {
						this.raiseCustomEvent("toolbar", "import_object", record);
					},
					scope: this
				},
				{
					text: IRm$.r1("L_INLINE_VIEW"),
					handler: function() {
						this.raiseCustomEvent("toolbar", "cmd_inlineview", record);
					},
					scope: this
				},
				{
					text: IRm$.r1("B_FOLDER"),
					iconCls: "icon-folder",
					hidden: ig$.features["ig_n_f_f"] !== false,
					handler: function() {
						this._createMetaObject("Folder", itemuid, itemaddr, record);
					},
					scope: this
				}
			];
			
			// if (ig$.$l_ < 5)
			// {
				smenu.push({
					text: IRm$.r1("B_DATASET"),
					// hidden: !me.__stagingdb,
					handler: function() {
						this._createMetaObject("DataSet", itemuid, itemaddr, record);
					},
					scope: this
				});
			// }
		}
		else if (issubcube == null)
		{
			smenu = [
				{
					text: IRm$.r1("B_FOLDER"),
					iconCls: "icon-folder",
					hidden: ig$.features["ig_n_f_f"] !== false,
					handler: function() {
						this._createMetaObject("Folder", itemuid, itemaddr, record);
					},
					scope: this
				},
				
				{
					text: IRm$.r1("L_REPORT"),
					iconCls: "icon-report",
					hidden: ig$.features["ig_n_rpt"] !== false,
					handler: function() {
						this._createMetaObject("Report", itemuid, itemaddr, record);
					},
					scope: this
				},
				{
					text: IRm$.r1("L_SQL_REPORT"),
					iconCls: "icon-sqlreport",
					hidden: ig$.features["ig_n_sqlrpt"] !== false,
					handler: function() {
						this._createMetaObject("SQLReport", itemuid, itemaddr, record);
					},
					scope: this
				},
				{
					text: IRm$.r1("L_UIPAGE"),
					hidden: true,
					handler: function() {
						this._createMetaObject("UIPage", itemuid, itemaddr, record);
					},
					scope: this
				},
				{
					text: IRm$.r1("L_DASHBOARD"),
					iconCls: "icon-dashboard",
					hidden: ig$.features["ig_n_dbd"] !== false,
					handler: function() {
						this._createMetaObject("Dashboard", itemuid, itemaddr, record);
					},
					scope: this
				},
				{
					text: IRm$.r1("L_BOBJ"),
					hidden: ig$.features["ig_n_bobj"] !== false,
					handler: function() {
						this._createMetaObject("Bobject", itemuid, itemaddr, record);
					},
					scope: this
				},
				{
					text: IRm$.r1("L_HD_BPROC"),
					hidden: ig$.features["ig_n_hb"] !== false,
					handler: function() {
						this._createMetaObject("BigData", itemuid, itemaddr, record);
					},
					scope: this
				},
				{
					text: IRm$.r1("L_BPMN_MODELER"),
					hidden: ig$.features["ig_bpmn_modeler"] !== false,
					handler: function() {
						this._createMetaObject("BPMN", itemuid, itemaddr, record);
					},
					scope: this
				}
			];
		}
		else if (issubcube == "cube")
		{
			smenu = [
				{
					text: IRm$.r1("B_FOLDER"),
					hidden: ig$.features["ig_n_f_f"] !== false,
					handler: function() {
						this._createMetaObject("Folder", itemuid, itemaddr, record);
					},
					scope: this
				},
				{
					text: IRm$.r1("L_CUSTOM_METRIC"),
					// hidden: (issubcube == "mcube") ? true : false,
					hidden: ig$.features["ig_n_cm"] !== false,
					handler: function() {
						this._createMetaObject("CustomMetric", itemuid, itemaddr, record);
					},
					scope: this
				}, 
				{
					text: IRm$.r1("L_HIERARCHY"),
					// hidden: (issubcube == "mcube") ? true : false,
					hidden: ig$.features["ig_n_hm"] !== false,
					handler: function() {
						this._createMetaObject("Hierarchy", itemuid, itemaddr, record);
					},
					scope: this
				},
				{
					text: IRm$.r1("L_DATE_METRIC"),
					hidden: ig$.features["ig_n_dm"] !== false,
					// hidden: (issubcube == "mcube") ? true : false,
					handler: function() {
						this._createMetaObject("DateMetric", itemuid, itemaddr, record);
					},
					scope: this
				}, 
				{
					text: IRm$.r1("L_MEASURE"),
					hidden: ig$.features["ig_n_ms"] !== false,
					handler: function() {
						this._createMetaObject("Measure", itemuid, itemaddr, record);
					},
					scope: this
				}, 
				{
					text: IRm$.r1("L_FORMULA"),
					hidden: ig$.features["ig_n_fm"] !== false,
					// hidden: (issubcube == "mcube") ? true : false,
					handler: function() {
						this._createMetaObject("FormulaMeasure", itemuid, itemaddr, record);
					},
					scope: this
				},
				{
					text: IRm$.r1("L_CHART_MEASURE"),
					hidden: ig$.features["ig_n_cms"] !== false,
					handler: function() {
						this._createMetaObject("ChartMeasure", itemuid, itemaddr, record);
					},
					scope: this
				},
				{
					text: IRm$.r1("L_GROUP_MEASURE"),
					hidden: ig$.features["ig_n_gm"] !== false,
					hidden: (issubcube == "mcube" ? false : true),
					handler: function() {
						this._createMetaObject("MeasureGroup", itemuid, itemaddr, record);
					},
					scope: this
				}
			];
		}
		else if (isrfolder)
		{
			smenu = [
				{
					text: IRm$.r1("B_FOLDER"),
					hidden: ig$.features["ig_n_f_f"] !== false,
					handler: function() {
						this._createMetaObject("Folder", itemuid, itemaddr, record);
					},
					scope: this
				},
				{
					text: IRm$.r1("B_RSCRIPT"),
					hidden: ig$.features["ig_n_f_r"] !== false,
					handler: function() {
						this._createMetaObject("RScript", itemuid, itemaddr, record);
					},
					scope: this
				}
			];
		}
		
		if (writable == true)
		{
			menu.add({
				text: IRm$.r1("L_MAKEITEM_G"),
				hidden: ig$.features["ig_n_f"] !== false,
				menu: smenu,
				scope: this
			});
		}
		
		if (instance.dlgLogin.jS2 == true)
		{
			menu.add({
				text: IRm$.r1("L_EXPORT_META"),
				hidden: ig$.features["ig_n_exp"] !== false,
				handler: function() {
					this.exportMeta({
						uid: itemuid,
						name: itemname,
						nodepath: itemaddr,
						type: typename
					});
				},
				scope: this
			});
		}
		
		if (typename != "folder" && typename != "rfolder" && typename != "javapackage")
		{
			menu.add({
				text: IRm$.r1((writable == true ? "L_EDIT_ITEM" : "L_VIEW_ITEM"), itemname),
				handler: function() {
					topPanel && topPanel.navigateApp(itemuid, typename, itemname, itemaddr, true, writable, {
						opt_editmode: writable
					});
				},
				scope: this
			});
			
			if (typename == "report" && ig$.features["ig_n_cp"] === false) // && ig$.$l_ < 5)
			{
				menu.add({
					text: IRm$.r1("L_COPY_ITEM", itemname),
					handler: function() {
						IG$.clipboard = {
							uid: itemuid,
							name: itemname,
							nodepath: itemaddr,
							type: typename
						};
					},
					scope: this
				});
			}
		}
		
		if (typename == "folder" && (writable == true || manageable == true) && IG$.clipboard != null) // ig$.$l_ < 5 && 
		{
			menu.add({
				text: IRm$.r1("L_PASTE_ITEM"),
				handler: function() {
					this.pasteMetaObject(record);
				},
				scope: this
			});
		}
		mvisible = true;
		break;
	case "table":
	case "inlineview":
		if (writable == true || manageable == true)
		{
			menu.add({
				text: IRm$.r1("B_FOLDER"),
				hidden: ig$.features["ig_n_f_f"] !== false,
				handler: function() {
					this._createMetaObject("Folder", itemuid, itemaddr, record);
				},
				scope: this
			});
		}
		break;
	case "bobject":
		if (data.leaf == false && (writable == true || manageable == true))
		{
			menu.add({
				text: IRm$.r1("B_FOLDER"),
				hidden: ig$.features["ig_n_f_f"] !== false,
				handler: function() {
					this._createMetaObject("Folder", itemuid, itemaddr, record);
				},
				scope: this
			});
		}
		
		if (data.leaf == true)
		{
			menu.add({
				text: IRm$.r1("L_BROWSE_ITEM", itemname),
				handler: function() {
					var rc = record;
					rc.data.leaf = false;
					rc.dirty = true;
					rc.appendChild({
						type: "load",
						name: "Loading"
					});
					rc.expand();
				},
				scope: this
			});
		}
		
		menu.add({
			text: IRm$.r1((writable == true ? "L_EDIT_ITEM" : "L_VIEW_ITEM"), itemname),
			handler: function() {
				topPanel && topPanel.navigateApp(itemuid, typename, itemname, itemaddr, true, writable, {
					opt_editmode: writable
				});
			},
			scope: this
		});
		mvisible = true;
		break;
	case "report":
	case "bigdata":
	case "javaclass":
	case "uipage":
	case "cubemodel":
	case "dataset":
	case "bpmn":
		menu.add({
			text: IRm$.r1((writable == true ? "L_EDIT_ITEM" : "L_VIEW_ITEM"), itemname),
			handler: function() {
				topPanel.navigateApp(itemuid, typename, itemname, itemaddr, true, writable, {
					opt_editmode: writable
				});
			},
			scope: this
		});
		break;
	case "dashboard":
		menu.add({
			text: IRm$.r1((writable == true ? "L_EDIT_ITEM" : "L_VIEW_ITEM"), itemname),
			handler: function() {
				topPanel && topPanel.navigateApp(itemuid, (writable ? "dashboardedit" : "dashboard"), itemname, itemaddr, true, true);
			},
			scope: this
		});

		mvisible = true;
		break;
	case "measure":
	case "hierarchy":
		menu.add({
			text: IRm$.r1((writable == true ? "L_EDIT_ITEM" : "L_VIEW_ITEM"), itemname),
			handler: function() {
				if (!IG$.measureEditor)
				{
					IG$.getScriptCache(
						ig$.bootconfig.scmap.igcn, 
						new IG$.callBackObj(this, function() {
							if (IG$.measureEditor)
							{
								var pop = new IG$.measureEditor({
									instance: me.instance,
									uid: itemuid, name: itemname
								});
								IG$.checkLogin(me, pop);
							}
							else
							{
								IG$.ShowError(IRm$.r1("L_ERR_L_MOD"));
							}
						})
					);
				}
				else
				{
					var pop = new IG$.measureEditor({
						instance: me.instance,
						uid: itemuid, name: itemname
					});
					IG$.checkLogin(me, pop);
				}
			}
		});
		break;
	case "formulameasure":
		menu.add({
			text: IRm$.r1((writable == true ? "L_EDIT_ITEM" : "L_VIEW_ITEM"), itemname),
			handler: function() {
				var pop = new IG$.formulaEditor({
					instance: me.instance,
					uid: itemuid, name: itemname
				});
				IG$.checkLogin(me, pop);
			}
		});
		break;
	case "chartmeasure":
		menu.add({
			text: IRm$.r1((writable == true ? "L_EDIT_ITEM" : "L_VIEW_ITEM"), itemname),
			handler: function() {
				var pop = new IG$.cellwizard({
					instance: me.instance,
					uid: itemuid, name: itemname
				});
				IG$.checkLogin(me, pop);
			}
		});
		break;
	case "datemetric":
		menu.add({
			text: IRm$.r1((writable == true ? "L_EDIT_ITEM" : "L_VIEW_ITEM"), itemname),
			handler: function() {
				var typename = record.get("type").toLowerCase(),
					itemname = record.get("name"),
					itemaddr = record.get("nodepath"),
					itemuid = record.get("uid"),
					writable = (record.get("writable") == "T" || record.get("manage") == "T") ? true : false,
					manageable = (record.get("manage") == "T") ? true : false,
					issubcube = record.get("issubcube");
				
				topPanel && topPanel.navigateApp(itemuid, typename, itemname, itemaddr, true, writable);
			}
		});
		break;
	case "custommetric":
		menu.add({
			text: IRm$.r1((writable == true ? "L_EDIT_ITEM" : "L_VIEW_ITEM"), itemname),
			handler: function() {
				if (!IG$.custommetric)
				{
					IG$.getScriptCache(
						ig$.bootconfig.scmap.igcn, 
						new IG$.callBackObj(this, function() {
							if (IG$.custommetric)
							{
								var pop = new IG$.custommetric({
									instance: me.instance,
									uid: itemuid, name: itemname
								});
								IG$.checkLogin(me, pop);
							}
							else
							{
								IG$.ShowError(IRm$.r1("L_ERR_L_MOD"));
							}
						})
					);
				}
				else
				{
					var pop = new IG$.custommetric({
						instance: me.instance,
						uid: itemuid, name: itemname
					});
					IG$.checkLogin(me, pop);
				}
			}
		});
		break;
	case "metric":
		menu.add({
			text: IRm$.r1((writable == true ? "L_EDIT_ITEM" : "L_VIEW_ITEM"), itemname),
			handler: function() {
				var mitem,
					rptptr = me.rptptr;
				
				if (meta_type == "sql_report")
				{
					var reportoption = rptptr.reportoption._mc,
						i, j, sql_obj;
					for (i=0; i < reportoption.inlineview_sql_objects.length; i++)
					{
						sql_obj = reportoption.inlineview_sql_objects[i]; 
						if (sql_obj.sql_id == record.get("sql_id"))
						{
							for (j=0; j < sql_obj.meta_dimensions.length; j++)
							{
								if (sql_obj.meta_dimensions[j].uid == itemuid)
								{
									mitem = sql_obj.meta_dimensions[j];
									mitem.writable = true;
									break;
								}
							}
							break;
						}
					}
					
					if (!mitem)
					{
						IG$.alertmsg(ig$.appname, IRm$.r1("M_NOTFOUND_IN_DIM"), null, null, 0, "error");
						return;
					}
				}
				
				var metric_callback = function() {
					if (mitem)
					{
						record.set("name", mitem.name);
						record.set("description", mitem.description);
						
						if (me.fireEvent)
						{
							me.fireEvent("node_rename", me, record);
						}
					}
				};
				
				if (!IG$.metricEditor)
				{
					IG$.getScriptCache(
						ig$.bootconfig.scmap.igcn, 
						new IG$.callBackObj(this, function() {
							if (IG$.metricEditor)
							{
								var pop = new IG$.metricEditor({
									instance: me.instance,
									rpt_meta_type: me.meta_type,
									uid: itemuid, 
									name: itemname,
									dmode_cnt: mitem,
									callback: new IG$.callBackObj(me, function() {
										metric_callback();
									})
								});
								IG$.checkLogin(me, pop);
							}
							else
							{
								IG$.ShowError(IRm$.r1("L_ERR_L_MOD"));
							}
						})
					);
				}
				else
				{
					var pop = new IG$.metricEditor({
						instance: me.instance,
						rpt_meta_type: me.meta_type,
						uid: itemuid, 
						name: itemname,
						dmode_cnt: mitem,
						callback: new IG$.callBackObj(me, function() {
							metric_callback();
						})
					});
					IG$.checkLogin(me, pop);
				}
			}
		});
		
		mvisible = true;
		break;
	case "qicustom":
		var stype = record.get("stype"),
			pmenu;
		if (stype && window.qicustom_menus.popupmenu && window.qicustom_menus.popupmenu[stype])
		{
			pmenu = window.qicustom_menus.popupmenu[stype];
			if (pmenu.length > 0)
			{
				$.each(pmenu, function(i, pm) {
					menu.add(
						{
							text: pm.text,

							handler: function() {
								if (window.qicustom_menus.popupmenu.handler) {
									var t_m = window.qicustom_menus.menuitems[record.get("uid")];
									window.qicustom_menus.popupmenu.handler.call(window, t_m, pm);
								}
							}
						}
					);
				});
				mvisible = true;
			}
		}
		break;
	default:
		break;
	}
	
	var av = instance.dlgLogin.jS2;
	
	if (typename != "qicustom" && (writable == true || manageable == true))
	{
		if (!is_priv && !is_dept && meta_type != "sql_report")
		{
			menu.add({
				text: IRm$.r1("L_RENAME_ITEM", IG$._gitemname(itemname)),
				hidden: ig$.features["ig_n_ren"] !== false,
				handler: function() {
					this._renameMetaObject(data.name, itemuid, itemaddr, record);
				},
				scope: this
			});
			
			menu.add({
				text: IRm$.r1("L_DELETE_ITEM", IG$._gitemname(itemname)),
				hidden: ig$.features["ig_n_del"] !== false,
				handler: function() {
					this.deleteMetaObject(itemuid, record);
				},
				scope: this
			});
			mvisible = true;
		}
	}
	
	if (typename != "qicustom" && typename != "folder" && (!record.isRoot || (record.isRoot && record.isRoot() == false))) // ig$.$l_ < 5 && 
	{
		if (typename == "report")
		{
			menu.add({
				text: IRm$.r1("L_COPY_ITEM", itemname),
				handler: function() {
					IG$.clipboard = {
						uid: itemuid,
						name: itemname,
						nodepath: itemaddr,
						type: typename
					};
				},
				scope: this
			});
			
			mvisible = true;
		}
		
		if (instance.dlgLogin.jS2 == true)
		{
			if (ig$.features["ig_n_e_meta"] === false && !is_priv && !is_dept && meta_type != "sql_report")
			{
				menu.add({
					text: IRm$.r1("L_EDIT_META"),
					// hidden: ig$.features["ig_n_e_meta"] !== false,
					handler: function() {
						this.editMeta && this.editMeta({
							uid: itemuid,
							name: itemname,
							nodepath: itemaddr,
							type: typename
						});
					},
					scope: this
				});
			}
		}
	}
	
	if (typename != "qicustom" && manageable == true && meta_type != "sql_report")
	{
		menu.add({
			text: IRm$.r1("L_OBJECT_AUTH"),
			hidden: ig$.features["ig_n_oauth"] !== false,
			handler: function() {
				var dlgpop;
				dlgpop = new IG$.objectAuth({
					instance: me.instance,
					uid: itemuid, 
					itemtype: itemtype
				});
				
				IG$.checkLogin(this, dlgpop);
			},
			scope: this
		});
		
		menu.add({
			text: IRm$.r1("L_SUBSCRIBE"),
			hidden: ig$.features["ig_n_osubscr"] !== false,
			handler: function() {
				var dlgpop;
				dlgpop = new IG$.objectSubscribe({
					instance: me.instance,
					uid: itemuid, 
					itemtype: itemtype
				});
				
				IG$.checkLogin(this, dlgpop);
			},
			scope: this
		});
		
		/*
		if (typename == "folder" && ig$.$l_ > 5)
		{
			// do nothing
		}
		else
		{
		*/
			menu.add({
				text: IRm$.r1("L_REVISION"),
				hidden: ig$.features["ig_n_rev"] !== false,
				handler: function() {
					IG$.procMenuCommand(instance, "CMD_REVISION", itemuid);
				},
				scope: this
			});
		// }
		mvisible = true;
	}
	
	if (typename != "qicustom" && (typename == "folder" || data.leaf == false))
	{
		menu.add(
			{
				text: IRm$.r1("L_REFRESH"),
				handler: function() {
					this.refreshNode(record);
				},
				scope: this
			}
		);
	}
	
	if (typename != "qicustom" && manageable  == true)
	{
		menu.add(
			{
				text: IRm$.r1("L_MGR_FD"),
				hidden: ig$.features["ig_n_mgf"] !== false,
				handler: function() {
					this.manageFolder(record);
				},
				scope: this
			}
		);
	}
	
	return mvisible;
};

IG$.deleteMetaObject = function(uid, record, callback) {
	var me = this;
	IG$.confirmMessages(ig$.appname, IRm$.r1("M_CONFIRM_DELETE"), function(e) {
		if (e == "yes")
		{
			var req = new IG$._rpc$(),
				payloads = [],
				i;
			
			if (typeof(uid) == 'object' && uid.length)
			{
				for (i=0; i < uid.length; i++)
				{
					payloads.push({
						uid: uid[i],
						option: "delete"
					});
				}
				req.init(me, 
					{
						ack: "batchcontent",
						payload: payloads,
						mbody: {}
					}, me, me.rdeleteMetaObject ? me.rdeleteMetaObject : IG$.rdeleteMetaObject, null, [record, callback]);
			}
			else
			{
				req.init(me, 
					{
						ack: "deletecontent",
						payload: {uid: uid},
						mbody: {}
					}, me, me.rdeleteMetaObject ? me.rdeleteMetaObject : IG$.rdeleteMetaObject, null, [record, callback]);
			}
			req.send();
		}
	}, me, me);
}

IG$.rdeleteMetaObject = function(jdoc, params) {
	var me = this,
		record = params[0], 
		callback = params[1];
	
 // record.remove(); -- sencha version 4.2.3
	me.selectedNode = [];
	IG$.alertmsg(ig$.appname, IRm$.r1("M_DELETED"), null, me, 0, "success");
	
	if (me.fireEvent)
	{
		let r = me.fireEvent("refreshTree", me, record);
		
		if (r)
			return;
	}
	
	if (callback)
	{
		callback.execute();
	}
	else if (record && me.refreshNode)
	{
		me.refreshNode(record.parentNode);
	}
}

IG$._itemEditCtrlMap = {
	measure: "measureEditor",
	hierarchy: "HierarchyEditor",
	custommetric: "custommetric",
	datemetric: "datemetric",
	formulameasure: "formulaEditor",
	chartmeasure: "cellwizard",
	udg: "_udgeditor"
}

IG$._createMetaObject = function(objecttype, parentuid, parentfullpath, node, callback) {
	// create object directly with object type
	var me = this,
		dlgpop,
		objeditor = IG$._itemEditCtrlMap[objecttype.toLowerCase()];
	
	if (objeditor)
	{
		dlgpop = new IG$[objeditor]({
			instance: me.instance,
			parentnodepath: parentfullpath,
			itemtype: objecttype,
			parentuid: parentuid,
			callback: me.r_createMetaObject ? new IG$.callBackObj(me, me.r_createMetaObject, [node, callback]) : callback
		});
	}
	else
	{
		dlgpop = new IG$.makeItem({
			instance: me.instance,
			parentnodepath: parentfullpath,
			itemtype: objecttype,
			parentuid: parentuid,
			callback: me.r_createMetaObject ? new IG$.callBackObj(me, me.r_createMetaObject, [node, callback]) : callback
		});
	}
	
	IG$.checkLogin(this, dlgpop);
},

IG$.r_createMetaObject = function(jdoc, param) {
	var me = this,
		instance = me.instance,
		node = param[0],
		callback = param[1],
		r, item,
		main_panel = instance.mainPanel;
	
	if (jdoc && main_panel && (jdoc.type == "Bobject" || jdoc.type == "Report" || jdoc.type == "SQLReport"))
	{
		item = jdoc;
		main_panel.navigateApp(item.uid, item.type.toLowerCase(), item.name, item.uid, true, item.writable, {
			opt_editmode: item.writable
		});
	}
	
	if (me.fireEvent)
	{
		r = me.fireEvent("refreshTree", me, node);
		
		if (r)
			return;
	}
	
	node && me.refreshNode && me.refreshNode(node);
	!node && me.refreshCurrent && me.refreshCurrent();
	
	callback && callback.execute();
};

