IG$.pivotFilterEditor = $s.extend(IG$.v$pnl, {
	layout: "fit",
	
	activeSheet: 0,
	
	loadReport: function(p) {
		var me = this,
			req;
		
		me.uid = p.uid;
		
		req = new IG$._rpc$();
		req.init(me,
			{
				ack: "content",
				payload: {uid: me.uid, revision: me.revision},
				mbody: {}
			}, me, function(jdoc) {
				me.reportoption = new IG$.clReports(jdoc, jdoc.content ? jdoc.content.meta_type : null);
				
				var browser = me.down("[name=browser]"),
					feditor = me.down("[name=feditor]"),
					p_opeditor = me.down("[name=p_opeditor]");
				
				if (me.reportoption.sheets.length > 0)
				{
					me.sheetoption = me.reportoption.sheets[0];
					me.cubeuid = me.sheetoption.cubeuid || me.reportoption.cubeuid;
					var reportmode = me.sheetoption.reportmode || me.reportoption.reportmode;
					var values = {};
					values.type = (reportmode == "rolap") ? "Cube" : "Metric";
					values.name = values.type;
					values.nodepath = values.type;
					values.uid = me.cubeuid || null;
						
					values.leaf = false;
			
					browser.setRootNode.call(browser, values);
					
					browser.show();
					
					feditor.reportoption = me.reportoption;
					feditor.sheetoption = me.sheetoption;
					
					feditor.in$t.call(feditor);
					
					feditor.show();
					
					p_opeditor.reportoption = me.reportoption;
					p_opeditor.sheetoption = me.sheetoption;
					p_opeditor.show();
				}
			}, false);
		req.send();
	},
	
	requestSQLResult: function(c, cb) {
		var me = this,
			feditor = me.down("[name=feditor]");
		
		me._lsql = [];
		me._ldb = [];
		
		if (me.sheetoption != null && me.reportoption != null)
		{
			feditor.confirmFilterSetting.call(feditor);
			
			var pivotxml = me.reportoption.getCurrentPivot.call(me.reportoption),
				req = new IG$._rpc$();
				
			req.init(me, 
				{
					ack: "olapservice",
					payload: {uid: me.uid, option: "sql", active: "" + me.activeSheet},
					mbody: pivotxml
				}, me, function(jdoc) {
					var tnode = IG$.XGetNode(jdoc, '/smsg/item/ExecuteQuery'),
						sql;
					if (tnode)
					{
						sql = IG$.XGetTextVal(tnode);
						me._lsql.push(sql);
					}
					
					c && cb && cb.call(c, 1);
				}, function(jdoc) {
					c && cb && cb.call(c, false);
				});
			req.send();
		}
	},
	
	set_count: function(counts) {
		var me = this,
			feditor = me.down("[name=feditor]");
		
		feditor.set_count.call(feditor, counts);
	},
	
	initComponent: function() {
		var panel = this;
		
		$s.apply(this, {
			items: [
				{
					xtype: "panel",
					layout: "border",
					items: [
						{
							xtype: "panel",
							title: IRm$.r1("L_pf_navitree"),
							layout: "fit",
							split: true,
							region: "west",
							flex: 1,
							border: 0,
							items: [
								new IG$.naviTree({
									instance: me.instance,
									showtoolbar: false,
									name: "browser",
									hidden: true,
									cubebrowse: true,
									collapsible: false,
									floatable: false,
									floating: false,
									ddGroup: "_I$RD_G_",
									layout: "fit",
									enabledrag: true,
									_search: true,
									
									custDblClickFunc: new IG$.callBackObj(this, function(record) {
										var me = this;
											p_opeditor = me.down("[name=p_opeditor]"),
											filter = new IG$.clFilter(null);
										
										filter.operator = 6;
										
										p_opeditor.filteritem = filter;
										p_opeditor.init_f.call(p_opeditor);
										p_opeditor.itemSelectedHandler.call(p_opeditor, record.data);
									})
								})
							]
						},
						{
							xtype: "panel",
							layout: "border",
							region: "center",
							split: true,
							flex: 2,
							items: [
								{
									xtype: "panel",
									title: IRm$.r1("L_pf_fedit"),
									split: true,
									padding: ig$.padding,
									layout: "fit",
									flex: 1,
									region: "north",
									items: [
										new IG$.filterEditorPanel({
											instance: me.instance,
											name: "p_opeditor",
											hidden: true,
											autoScroll: false,
											_cmode: 1,
											flex: 1
										})
									]
								},
								{
									xtype: "panel",
									split: true,
									region: "center",
									title: IRm$.r1("L_pf_filter"),
									flex: 1,
									layout: "fit",
									items: [
										new IG$.filterMainEditor({
											instance: me.instance,
											name: "feditor",
											hidden: true,
											deferredRender: false,
											padding: ig$.padding
										})
									]
								}
							]
						}
					]
				}
			]
		});
		IG$.pivotFilterEditor.superclass.initComponent.call(this);
	},
	listeners: {
		afterrender: function(tobj) {
			var me = tobj,
				p_opeditor = me.down("[name=p_opeditor]"),
				feditor = me.down("[name=feditor]");
			
			p_opeditor.on("add_filter", function(ed) {
				ed._confirm.call(ed);
				var dt = ed.filteritem,
					tnode;
					
				tnode = feditor.rootnode_w.children[0];
				
				feditor.rs_appendCondition.call(feditor, [tnode, dt]);
			});
			p_opeditor.init_f.call(p_opeditor);
		}
	}
});

IG$.pivotFilter = IG$.extend(IG$.ctrlBase, {
	initComponent: function() {
		var me = this;
		
		me.p.push(
			{name: "report_control", type: "property", datatype: "string", vmode: 1},
			{name: "filter_id", type: "property", datatype: "string", vmode: 1},
			{name: "flexHeight", type: "property", datatype: "number", value: 0},
			{name: "minHeight", type: "property", datatype: "number", value: 0},
			{name: "itemclick", type: "event"}
		);
		
		me.superclass.prototype.initComponent.call(me);
	},
	
	processEvent: function(evttype, obj) {
	},
	
	invalidate: function () {
		var me = this,
			w = IG$.j$ext._w(me.html),
			h = IG$.j$ext._h(me.html);
			
		if (me.viewer)
		{
			me.renderto.width(w).height(h);
			me.viewer.setSize(w, h);
		}
	},
	
	valid: function() {
		var r = 0;
		
		return r;
	},
	
	confirmFilter: function(mode, c, cb) {
		var me = this,
			r,
			ctrl = me.ctrl,
			dashboard = ctrl.dashboard;
		
		me.viewer.requestSQLResult.call(me.viewer, me, function(r) {
			var cr;
			
			if (r != false)
			{
				try
				{
					cr = cb.call(c, r);
				}
				catch (e)
				{
					cr = false;
					IG$.ShowError(IRm$.r1("E_FILTER_SCRIPT"), null, null, {errstack: e.stack});
				}
			}
		
			if (r != false && cr != false)
			{
				dashboard.contEventProc.call(dashboard, dashboard);
			}
			else
			{
				dashboard.stopEventProc.call(dashboard, dashboard);
			}
		});
	},
	
	applyApplication: function () {
	},
	initDrawing: function () {
		var me = this,
			w = IG$.j$ext._w(me.html),
			h = IG$.j$ext._h(me.html),
			renderto = $("<div></div>").appendTo(me.html),
			actionlist = me.ctrl.actionlist;
		
		IG$.j$ext._w(renderto, w);
		IG$.j$ext._h(renderto, h);
		
		me.viewer = me.dsmode ? null : new IG$.pivotFilterEditor({
			width: IG$.j$ext._w(renderto),
			height: IG$.j$ext._h(renderto),
			renderTo: renderto[0]
		});
		
		me.renderto = renderto;
		
		me.__pcinit();
	},
	updateProperty: function(kname, value) {
		var me = this;
		
		if (me.dsmode)
		{
			return;
		}
		
		switch(kname)
		{
		case "report_control":
			me.__ivp();
			break;
		}
	},
	__ivp: function() {
		var me = this,
			property = me.property,
			report_control = property["report_control"],
			filter_id = property["filter_id"],
			rptctrl,
			i,
			dashboard = me.ctrl.dashboard,
			dctrl;
			
		if (me.dsmode || me.__pcinit_)
		{
			return;
		}
			
		if (report_control && dashboard && dashboard.ControlDict)
		{
			setTimeout(function() {
				var dctrl,
					dobj;
				dctrl = dashboard.ControlDict[report_control];
				if (dctrl && filter_id)
				{
					dobj = dctrl.control;
					dobj.negoFilter && dobj.negoFilter.call(dobj, me, filter_id);
				}
			}, 20);
		}
	},
	
	set_base_report: function(rpt, cobj, cback) {
		var me = this,
			req = new IG$._rpc$();
		req.init(me,
			{
				ack: "helpcontent",
				payload: {uid: rpt},
				mbody: {option: 'translate'}
			}, me, function(jdoc) {
				var p = jdoc;
					
				if (p && p.uid)
				{
					me.viewer.loadReport.call(me.viewer, p);
				}
			}, false);
		req.send();
	},

	get_sql: function(delimiter) {
		var me = this;
		return me.viewer._lsql.join(delimiter || ";");
	},
	
	get_db: function(delimiter) {
		var me = this;
		return me.viewer._ldb.join(delimiter || ";");
	},
	
	set_count: function(counts) {
		this.viewer.set_count.call(this.viewer, counts);
	}
});

IG$.controls.pivotfilter = new IG$.pivotFilter({}, null);

