
/**
 * label control
 */
IG$._FC_label = $s.extend(IG$._baseFC, {
	objtype: "label",
	events: [
		{name: "click"}
	],
	properties: [
		{name: "style", type: "enum", values: ["maintitle", "subtitle", "normal"]}
	],
	create: function(container) {
		var me = this,
			fmodel = me.fmodel,
			fitem = me.fitem,
			mcap = me.mcap,
			stext = fmodel.title || " ",
			ui;
			
		ui = $("<div></div>")
			.appendTo(container);
		me.text(stext, ui);
		return ui;
	},
	
	text: function(value, ui) {
		var me = this,
			div = ui || me.ui,
			value = value || " ";
		if (value.length > 1 && value.charAt(0) == '{' && value.charAt(value.length-1) == '}')
		{
			value = IRm$.r1(value.substring(1, value.length-1));
		}
		
		div.html(value);
	},
	
	$setProp: function(fitem, key, value) {
		var me = this;
		switch (key)
		{
		case "title":
			me.text(value);
			break;
		case "style":
			if (me._astyle && me._astyle != value)
			{
				me.ui.removeClass(me._astyle);
			}
			value && me.ui.addClass(value);
			me._astyle = value;
			break;
		}
		
		IG$._baseFC.prototype.$setProp.call(me, fitem, key, value);
	}
});

IG$.$FCinst["label"] = new IG$._FC_label();