IG$.burst_config = $s.extend($s.window, {
	
	modal: true,
	region:'center',
	layout: "fit",
	
	closable: false,
	resizable:false,
	width: 500,
	height: 450,	
	
	callback: null,
	
	init_f: function() {
		var me = this,
			reportoption = me.reportoption ? me.reportoption._mc : null,
			sheetoption = me.sheetoption.model,
			items,
			i,
			dataquerymode = sheetoption.dataquerymode,
			fields = dataquerymode == "M_DATA" ? ["rows"] : ["rows"],
			email_field = me.down("[name=email_field]"),
			dp = [];
			
		sheetoption.formbuilder = sheetoption.formbuilder || IG$.formViewerDefault;
		
		$.each(fields, function(i, k) {
			var arr = sheetoption[k],
				n, p;
			
			if (arr)
			{
				for (n=0; n < arr.length; n++)
				{
					p = IG$.copyObject(arr[n]);
					p.iconcls = IG$.get_metatype_icon(p.type.toLowerCase(), p);
					dp.push(p);
				}
			}
		});
		
		email_field.store.loadData(dp);
		
		me.setAllValues(sheetoption.formbuilder);
	},
	
	_confirm: function() {
		var me = this,
			gdp1 = me.down("[name=email_field]"),
			gdp1_sel = gdp1.getSelectionModel().selected,
			dp1 = [],
			rec,
			i;
			
		for (i=0; i < gdp1_sel.length; i++)
		{
			rec = gdp1_sel.items[i];
			dp1.push(rec.get("uid"));
		}
				
		me.close();
	},
	
	initComponent: function() {
		$s.apply(this, {
			title: IRm$.r1("T_BURST_CONFIG"),
			
			items: [
				{
					xtype: "panel",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					bodyBorder: false,
					padding: ig$.padding,
					items: [
						{
							xtype: "fieldset",
							title: IRm$.r1("L_BURST_EMAIL"),
							flex: 1,
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "gridpanel",
									name: "email_field",
									flex: 1,
									store: {
										fields: ["name", "uid"]
									},
									selModel: {
										mode: "SINGLE",
										checkSelector: ".x-grid-cell"
									},
									selType: "checkboxmodel",
									columns: [
										{
											text: IRm$.r1("B_NAME"),
											dataIndex: "name",
											flex: 1
										}
									]
								}
							]
						}
					]
				}
			],
			buttons:[
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, {
					text: IRm$.r1('B_CANCEL'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(ui) {
					var panel = this;
					panel.init_f();
				}
			}
		});
		
		IG$.burst_config.superclass.initComponent.apply(this, arguments);
	}
});