IG$.cVis.map = $s.extend(IG$.cVis.protovis, {
	subtype: "map",

	centroid: function(pts) {
		var nPts = pts.length;
		var lng=0; var lat=0;
		var f;
		var j=nPts-1;
		var p1; var p2;
	 
		for (var i=0;i<nPts;j=i++) {
		   p1=pts[i]; p2=pts[j];
		   f=p1.lng*p2.lat-p2.lng*p1.lat;
		   lng+=(p1.lng+p2.lng)*f;
		   lat+=(p1.lat+p2.lat)*f;
		}
	 
		f=this.area(pts)*6;
		return {lng:lng/f, lat:lat/f};
	},
	 
	draw_protovis: function(mresult) {
		 var latlng,
			 mapid,
			 geomaptype = "d3ext",
			 me = this;
	 
		 if (geomaptype == "google")
		 {
			 mapid = "map__US"
			 if (typeof(IG$.geoDatas[mapid]) == "undefined")
			 {
				 me.ldMapData("US", "", mapid, "ploc", me);
				 return;
			 }
	 
			 var mapdata = IG$.geoDatas[mapid];
	 
			 latlng = new google.maps.LatLng(37.09024, -95.712891);
	 
			 var myOptions = {
			   zoom: 4,
			   center: latlng,
			   mapTypeId: google.maps.MapTypeId.ROADMAP
			 };
	 
			 var map = new google.maps.Map(me.container, myOptions);
	 
			 if (typeof(mapdata) != "undefined")
			 {
				 var i,
					 j,
					 radmax = 180000,
					 radmin = 3000;
	 
				 var mdata = {};
				 var tmax = NaN;
				 var tmin = NaN;
	 
				 for (i=mresult.rowfix; i < mresult._tabledata.length; i++)
				 {
					 var mcode = mresult._tabledata[i][0].text;
	 
					 if (typeof(mapdata.data[mcode]) != "undefined")
					 {
						 var svalue = 0;
						 var mvalue;
						 for (j=mresult.colfix; j < mresult.colcnt; j++)
						 {
							 mvalue = mresult._tabledata[i][j].code;
							 svalue += Number(mvalue);
						 }
	 
						 if (typeof(mdata[mcode]) == "undefined")
						 {
							 mdata[mcode] = {};
							 mdata[mcode].lat = mapdata.data[mcode].lat;
							 mdata[mcode].lng = mapdata.data[mcode].lng;
	 
							 mdata[mcode].value = svalue;
	 
							 tmax = (isNaN(tmax) == true) ? svalue : Math.max(tmax, svalue);
							 tmin = (isNaN(tmin) == true) ? svalue : Math.min(tmin, svalue);
						 }
						 else
						 {
							 mdata[mcode].value += svalue;
							 tmax = Math.max(tmax, mdata[mcode].value);
							 tmin = Math.min(tmin, mdata[mcode].value);
						 }
					 }
				 }
	 
				 for (var key in mdata)
				 {
					 latlng = new google.maps.LatLng(mdata[key].lat, mdata[key].lng);
					 var depth = (tmax - tmin == 0) ? 1 : ((mdata[key].value - tmin) / (tmax - tmin));
					 var cradius = (radmax - radmin) * depth;
					 var ccolor = IG$.interpolateColor("153a6f", "a7d6ef", 10, depth * 10);
					 var circleOption = {
						 center: latlng,
						 radius: cradius,
						 strokeColor: "#efefef",
						 strokeOpacity: .5,
						 strokeWeight: 1,
						 fillColor: ccolor,
						 fillOpacity: .6
					 };
	 
					 var circle = new google.maps.Circle(circleOption);
					 circle.setMap(map);
				 }
			 }
		 }
		 else if (geomaptype == "protovis")
		 {
			 me.drProtovisMapChart(mresult);
		 }
		 else if (geomaptype == "d3")
		 {
			 me.drD3Map(mresult);
		 }
		 else if (geomaptype == "gsapi")
		 {
			 // google.load("visualization", "1", {packages: ["geochart"]});
			 // google.setOnLoadCallback(me.drawGSAPIMapChart);
			 me.drGSAPIMap();
		 }
		 else if (geomaptype == "d3ext")
		 {
			 me.drD3ExtMapLD(mresult);
		 }
	 },
	 
	drProtovisMapChartLD: function(mresult) {
		 var me = this;
		 var col = function(v) {
		   if (v < 17) return "#008038";
		   if (v < 20) return "#A3D396";
		   if (v < 23) return "#FDD2AA";
		   if (v < 26) return "#F7976B";
		   if (v < 29) return "#F26123";
		   if (v < 32) return "#E12816";
		   return "#B7161E";
		 };
	 
		 us_lowres.forEach(function(c) {
		   c.code = c.code.toUpperCase();
		   c.centLatLon = me.centroid(c.borders[0]);
		 });
	 
		 var us_stats = [];
	 
		 for (i=mresult.rowfix; i < mresult._tabledata.length; i++)
		 {
			 var mcode = mresult._tabledata[i][0].text;
			 var svalue = 0;
			 var mvalue;
			 for (j=mresult.colfix; j < mresult.colcnt; j++)
			 {
				 mvalue = mresult._tabledata[i][j].code;
				 svalue += Number(mvalue);
			 }
			 us_stats[mcode] = svalue;
		 }
	 
		 // Add the main panel
		 var jdom = $(me.container),
			 w = IG$.j$ext._w(jdom),
			 h = IG$.j$ext._h(jdom);
	 
		 var scale = pv.Geo.scale()
			 .domain({lng: -128, lat: 24}, {lng: -64, lat: 50})
			 .range({x: 0, y: 0}, {x: w, y: h});
	 
		 me.vismargin = {top: 30, bottom: 20}
		 me.vis = new pv.Panel()
			 .canvas(me.container)
			 .width(w)
			 .height(h - me.vismargin.top - me.vismargin.bottom)
			 .top(30)
			 .bottom(20);
	 
		 // Add the ticks and labels for the year slider
		 /*
		 me.vis.add(pv.Rule)
			 .data(pv.range(us_stats.minYear, us_stats.maxYear + .1))
			 .left(yearsScale)
			 .height(4)
			 .top(-20)
		   .anchor("bottom").add(pv.Label);
		 */
		 // Add a panel for each state
		 var state = me.vis.add(pv.Panel)
			 .data(us_lowres);
	 
		 // Add a panel for each state land mass
		 state.add(pv.Panel)
			 .data(function(c) {return c.borders})
		   .add(pv.Line)
			 .data(function(l) {return l})
			 .left(scale.x)
			 .top(scale.y)
			 .fillStyle(function(d, l, c) {return col(us_stats[c.code])})
			 .lineWidth(1)
			 .strokeStyle("white")
			 .antialias(false);
	 
		 // Add a label with the state code in the middle of every state
		 me.vis.add(pv.Label)
			 .data(us_lowres)
			 .left(function(c) {return scale(c.centLatLon).x})
			 .top(function(c) {return scale(c.centLatLon).y})
			 .text(function(c) {return c.code})
			 .textAlign("center")
			 .textBaseline("middle");
	 
		 // Add the color bars for the color legend
		 me.vis.add(pv.Bar)
			 .data(pv.range(14, 32.1, 3))
			 .bottom(function(d) {return this.index * 12})
			 .height(10)
			 .width(10)
			 .left(5)
			 .fillStyle(function(d) {return col(14 + 3 * this.index)})
			 .lineWidth(null)
		   .anchor("right").add(pv.Label)
			 .textAlign("left")
			 .text(function(d) {return d + " - " + (d + 3) + "%"});
	 
		 me.vis.render();
	},
	 
	drD3MapLD: function(mresult) {
		 var me = this;
		 var col = function(v) {
		   if (v < 17) return "#008038";
		   if (v < 20) return "#A3D396";
		   if (v < 23) return "#FDD2AA";
		   if (v < 26) return "#F7976B";
		   if (v < 29) return "#F26123";
		   if (v < 32) return "#E12816";
		   return "#B7161E";
		 };
	 
		 var path = d3.geo.path();
	 
		 var svg = d3.select(me.container)
		   .append("svg");
	 
		 var counties = svg.append("g")
			 .attr("id", "counties")
			 .attr("class", "Blues");
	 
		 var states = svg.append("g")
			 .attr("id", "states");
	 
		 d3.json("./data/us-counties.json", function(json) {
		   counties.selectAll("path")
			   .data(json.features)
			 .enter().append("path")
			   .attr("class", data ? quantize : null)
			   .attr("d", path);
		 });
	 
		 d3.json("./data/us-states.json", function(json) {
		   states.selectAll("path")
			   .data(json.features)
			 .enter().append("path")
			   .attr("d", path);
		 });
	 
		 var us_stats = [];
	 
		 for (i=mresult.rowfix; i < mresult._tabledata.length; i++)
		 {
			 var mcode = mresult._tabledata[i][0].text;
			 var svalue = 0;
			 var mvalue;
			 for (j=mresult.colfix; j < mresult.colcnt; j++)
			 {
				 mvalue = mresult._tabledata[i][j].code;
				 svalue += Number(mvalue);
			 }
			 us_stats[mcode] = svalue;
		 }
	 
		   counties.selectAll("path")
		   .attr("class", quantize);
	 
		 function quantize(d) {
		   return "q" + Math.min(8, ~~(us_stats[d.id] * 9 / 12)) + "-9";
		 }
	 },
	 
	 drD3ExtMapLD: function(mresult) {
		 var me = this,
			 url, i, j, cell, row,
			 fc = mresult.colfix,
			 fr = mresult.rowfix,
			 data = mresult._tabledata,
			 tc = (data.length > 0) ? data[0].length : 0,
			 container = me.container,
			 cop = me.chart_option,
			 sop = me.sheetoption ? me.sheetoption.model : null,
			 mapcategory = cop.mapcategory,
			 categindex = -1,
			 mapdata = (IG$.mLU ? IG$.mLU.maptype : null),
			 mapinfo = null,
			 mapdp = {},
			 dimname, n, c,
			 valuename,
			 mapelement,
			 name,
			 mapseries = [],
			 col = function(v) {
			   if (v < 17) return "#008038";
			   if (v < 20) return "#A3D396";
			   if (v < 23) return "#FDD2AA";
			   if (v < 26) return "#F7976B";
			   if (v < 29) return "#F26123";
			   if (v < 32) return "#E12816";
			   return "#B7161E";
			 },
			 mcr = me.sheetoption.model.chart_option,
			 sep = (mcr ? mcr.xaxissep : null) || ig$.chart_separator || IG$._separator;
			 
		 sep = sep == "nl" ? "\n" : sep;
	 
		 if (mapdata)
		 {
			 for (i=0; i < mapdata.length; i++)
			 {
				 if (mapdata[i].subtype == cop.maptype)
				 {
					 mapinfo = mapdata[i];
					 break;
				 }
			 }
		 }
	 
		 if (sop)
		 {
			 for (i=0; i < sop.rows.length; i++)
			 {
				 if (sop.rows[i].uid == mapcategory)
				 {
					 categindex = i;
					 break;
				 }
			 }
			 if (categindex < 0 && sop.rows.length > 0)
			 {
				 categindex = 0;
			 }
		 }
	 
		 if (mapinfo == null)
		 {
			 return;
		 }
	 
		 for (i=fc; i < tc; i++)
		 {
			 name = "";
	 
			 for (j=0; j < fr; j++)
			 {
				 cell = data[j][i];
				 name += (j > 0 ? sep : "") + (cell.text || cell.code);
			 }
	 
			 mapseries.push({
				 cindex: i,
				 c: i-fc,
				 name: name,
				 maxvalue: null,
				 minvalue: null,
				 sumvalue: 0
			 });
		 }
	 
		 for (i=fr; i < data.length; i++)
		 {
			 dimname = ((categindex > -1) ? data[i][categindex].code : "NO_REGION");
			 dimname = dimname ? dimname.toLowerCase() : "";
			 
			 valuename = ((categindex > -1) ? data[i][categindex].value : "NO_REGION");
			 valuename = valuename ? valuename.toLowerCase() : "";
	 
			 if (mapdp[dimname])
			 {
				 mapelement = mapdp[dimname];
			 }
			 else
			 {
				 mapdp[dimname] = mapelement = [];
				 for (j=0; j < mapseries.length; j++)
				 {
					 mapelement.push(0);
				 }
			 }
			 
			 if (dimname != valuename)
			 {
				 if (mapdp[valuename])
				 {
					 mapelement = mapdp[valuename];
				 }
				 else
				 {
					 mapdp[valuename] = mapelement = [];
					 for (j=0; j < mapseries.length; j++)
					 {
						 mapelement.push(0);
					 }
				 }
			 }
	 
			 for (j=fc; j < tc; j++)
			 {
				 c = j - fc;
				 cell = data[i][j];
				 n = (cell.code && cell.code != "") ? parseFloat(cell.code) : 0;
				 mapelement[c] += n;
				 mapseries[c].maxvalue = (mapseries[c].maxvalue == null) ? mapelement[c] : Math.max(mapseries[c].maxvalue, mapelement[c]);
				 mapseries[c].minvalue = (mapseries[c].minvalue == null) ? mapelement[c] : Math.min(mapseries[c].minvalue, mapelement[c]);
				 mapseries[c].sumvalue += n;
			 }
		 }
	 
		 url = "./data/" + mapinfo.filename;
	 
		 var callback = function(json) {
				 var canvas = $(container),
					 map = new gJ/*geomap*/(canvas),
					 _chartview = me.chartview;
				 /*
				 map1.drawMap(world_countries, {
					 mode: "azimuthal",
					 scale: 200,
					 azmode: "stereographic"
				 });
				 */
				 map.color = col;
				 map.clickHandler = {
					 o: me,
					 f: function(data) {
						 var sender = {
								 name: map.mapseries[map.legidx || 0].name
							 },
							 param = {
								 point: {
									 category: data.name || data.value
								 }
							 };
						 if (sender.name.charAt(sender.name.length-1) == " ")
						 {
							 sender.name = sender.name.substring(0, sender.name.length - 1);
						 }
						 // seriesname = (sender.series) ? sender.series.name : sender.name,
						 // categname = (param.point) ? param.point.category || param.point.name : "",
						 _chartview.procClickEvent(sender, param);
					 }
				 };
				 map.drawMap(json, {
					 scale: mapinfo.scale,
					 maptype: mapinfo.subtype,
					 mapseries: mapseries,
					 mapdp: mapdp
				 });
			 };
	 
			 // eventowner.procClickEvent(this, param);
	 
		 $.getJSON(url, callback)
	 },
	 
	 drGSAPIMapLD: function() {
		 var me = this,
			 container = me.container,
			 geochart = new google.visualization.GeoChart(container),
			 options= {region: "840"},
			 data = new google.visualization.DataTable();
		 data.addColumn("string", "State");
		 data.addColumn("number", "Data");
		 geochart.draw(data, options);
	 }
});