IG$.vsEdtr = $s.extend($s.window, {
	modal: true,
	layout: {
		type: 'fit',
		align: 'stretch'
	},
	
	closable: true,
	resizable: true,
	width: 400,
	height: 500,

	_init: function() {
		var me = this,
			ai_provider = ig$.ai_provider;
		
		$s.defaults(me.visual_story, {
			enabled: true,
			cssname: "normal",
			top: "10px",
			left: "10px"
		});
		
		me.down("[name=form_AIQ]").setVisible(ai_provider ? true : false);
		me.setAllValues(me.visual_story);
	},
	
	_confirm: function() {
		var me = this;
		
		if (me.getAllValues(me.visual_story))
			return;
		
		me.callback && me.callback.execute();
		me.close();
	},
	
	initComponent: function() {
		var me = this;
		
		$s.apply(me, {
			title: IRm$.r1("L_STORYIT"),
			padding: ig$.padding,
			items: [
				{
					xtype: "panel",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					padding: ig$.padding,
					autoScroll: true,
					items: [
						{
							xtype: "fieldset",
							title: IRm$.r1("B_GENERAL"),
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "checkbox",
									name: "enabled",
									fieldLabel: IRm$.r1("B_VISIBLE"), // "Visible",
									boxLabel: IRm$.r1("B_ENABLED") // "Enabled"
								},
								{
									xtype: "textfield",
									name: "cssname",
									fieldLabel: IRm$.r1("L_CSS_NAME") // "CSS name"
								},
								{
									xtype: "textfield",
									name: "condition",
									fieldLabel: IRm$.r1("L_CONDITION") // "Condition"
								}
							]
						},
						{
							xtype: "fieldset",
							title: "AI Questions",
							layout: {
								type: "vbox",
								align: "stretch"
							},
							name: "form_AIQ",
							items: [
								{
									xtype: "textarea",
									fieldLabel: IRm$.r1("L_AI_Q"), // "Template Context",
									name: "ai_questions"
								}
							]
						},
						{
							xtype: "fieldset",
							title: "Template",
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "textarea",
									fieldLabel: IRm$.r1("L_TEMPLATE_CONTEXT"), // "Template Context",
									name: "context"
								}
							]
						},
						{
							xtype: "fieldset",
							title: "Location",
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "textfield",
									name: "top",
									fieldLabel: IRm$.r1("B_TOP") // "Top"
								},
								{
									xtype: "textfield",
									name: "left",
									fieldLabel: IRm$.r1("B_LEFT") // "left"
								},
								{
									xtype: "textfield",
									name: "width",
									fieldLabel: IRm$.r1("B_WIDTH") // "Width"
								},
								{
									xtype: "textfield",
									name: "height",
									fieldLabel: IRm$.r1("B_HEIGHT") //"Height"
								},
								{
									xtype: "textfield",
									name: "bottom",
									fieldLabel: IRm$.r1("B_BOTTOM") // "bottom"
								},
								{
									xtype: "textfield",
									name: "right",
									fieldLabel: IRm$.r1("B_RIGHT") // "right"
								}
							]
						}
					]
				}
			],
			buttons: [
				"->",
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: me
				}, 
				{
					text: IRm$.r1('B_CANCEL'),
					handler:function() {
						this.close();
					},
					scope: me
				}
			],
			listeners: {
				afterrender: function(tobj) {
					me._init();
				}
			}
		});
		
		IG$.vsEdtr.superclass.initComponent.call(this);
	}
});