	onRender: function() {
	},
	
	doFilter: function() {
		var me = this,
			el = {
				menu: me.context
			},
			mdf = me._dfc.__af,
			cell = me.context.cell,
			fs = 0;
		
		if (me._dfc.f_opt.val() == "between")
		{
			if (me._dfc.sval1.val())
			{
				 me._dfc.sval2.focus();
			}
			else
			{
				fs = 1;
			}
		}
		else
		{
			if (me._dfc.sval1.val())
			{
				fs = 1;
			}
		}
		
		if (fs)
		{
			mdf[cell.c] = {
				op: me._dfc.f_opt.val(),
				val1: me._dfc.sval1.val(),
				val2: me._dfc.sval2.val()
			};
		}
		else
		{
			delete mdf[cell.c];
		}
		
		el.cmd = "cmd_run_filter".toUpperCase();
		el.menu.mdf = mdf[cell.c];
		
		me.fireEvent("menu", el);
		me._show_menu(false);
	},
	
	_show_menu: function(visible) {
		var me = this,
			_df = me._df;
		
		var _do_click = function(e) {
			$(document).unbind("mouseup", _do_click);
			_df.hide();
		};
		
		$(document).unbind("mouseup", _do_click);
		
		_df[visible ? "show" : "hide"]();
		
		$(document).bind("mouseup", _do_click);
	},
	
	_hookKeyEvt: function() {
		var me = this,
			focusableElement = me._focElm;
		
		if (focusableElement)
		{
			focusableElement.bind("keydown", function(ev) {
				//clipboard copy tracking
				if (ev.keyCode == 67 && (ev.ctrlKey == true || ev.metaKey))
				{
					me._copyclip();
					ev.preventDefault();
					ev.stopImmediatePropagation();
				}
				else if (ev.keyCode == 65 && (ev.ctrlKey == true || ev.metaKey))
				{
					me._selectAll();
					ev.preventDefault();
					ev.stopImmediatePropagation();
				}
			});
		}
	},
	
	_selectAll: function() {
		var me = this,
			i, j;
		
		me.removeAllSelection();
						
		for (i=0; i < me.rows.length; i++)
		{
			if (me.rows[i].visible !== false && me.rows[i]._treeCollapsed !== true)
			{
				for (j=0; j < me.cols.length; j++)
				{
					if (me.cols[j].visible !== false)
					{
						me[(this._treecol > -1 || this._treerow > -1) ? "treeData" : "_dataSet"][i][j].selected = true;
						me.selectedItems.push(me[(this._treecol > -1 || this._treerow > -1) ? "treeData" : "_dataSet"][i][j]);
					}
				}
				
				me.selectedRows.push(me.rows[i]);
			}
		}
		me.refreshSelect();
	},
	
	_copyclip: function() {
		var me = this,
			focusableElement = me._focElm,
			value = "",
			r = [], pn, i, rec,
			selection = me.selectedItems;
		
		if (selection && selection.length)
		{
			pn = -1;
        	for (i=0; i < selection.length; i++)
        	{
        		rec = selection[i];
        		
        		if (i > 0 && selection[i-1]._n_ == rec._n_)
        		{
        			r.push("\t");
        		}
        		
        		r.push(rec.text || rec.value);
        		
        		if (i + 1 < selection.length && selection[i+1]._n_ != rec._n_) 
        		{
        			r.push("\n");
        		}
        	}
        	
        	value = r.join("");
		}
		
		if(window.clipboardData)
		{
			window.clipboardData.setData("Text", value);
		}
		else if (focusableElement)
		{
			focusableElement.val(value);
			focusableElement.focus();
			focusableElement.select();
			
			document.execCommand("copy");
		}
	},
	
