	onThumbMouseDown: function(elem, ev, direction) {
		var owner = this,
			pg
		
		if (ev)
		{
			ev.preventDefault();
			ev.stopImmediatePropagation();
			
			pg = owner.gl_pos(ev);
			owner.dt1 = new Date().getTime();
			owner.thumbBtnDown = true;
			owner.thumbMouseSX = pg.pageX;
			owner.thumbMouseSY = pg.pageY;
			owner.sx = owner._scrollX;
			owner.sy = owner._scrollY;
			owner._isScrolling = true;
			owner.scrolltarget = elem.eventtarget;
			
			owner.regGlobalEvent(direction);
		}
		
		return false;
	},
	
	onThumbMouseUp: function(elem, ev, direction) {
		var me = this,
			owner = me,
			cdt = new Date().getTime();
		
		if (ev && me.dt1 && me.dt1 > -1 && cdt - me.dt1 < 200)
		{
			var je = $(elem),
				offset = je.offset(),
				px = ev.pageX - offset.left,
				py = ev.pageY - offset.top,
				pw = IG$.j$ext._w(je), // je.width(),
				ph = IG$.j$ext._h(je), // je.height(),
				nsx = me._scrollX,
				nsy = me._scrollY,
				step, inc;
			
			me.dt1 = -1;
			
			event.stopPropagation();
			
			if (me.ge)
			{
				$(document).unbind(me.ge);
				me.ge = null;
			}
			
			if (me.getc)
			{
				$(me.owner).unbind(me.getc);
				me.getc = null;
			}
			
			me.glMouseUp(ev, direction);
			
			owner.thumbBtnDown = false;
			owner.thumbMouseSX = -1;
			owner.thumbMouseSY = -1;
			
			if (direction == "v")
			{
				inc = (py > ph / 2) ? 0.1 : -0.1;
				step = Math.min(owner._theight - owner._cheight, (owner._cheight) * 0.1);
				nsy = nsy + step * inc;
				nsy = (nsy < 0) ? 0 : Math.min(nsy, owner._theight - owner._cheight);
			}
			else if (direction == "h")
			{
				inc = (px > pw / 2) ? 0.1 : -0.1;
				step = step = Math.min(owner._twidth - owner._dwidth, (owner._dwidth - owner._fixedRowW) * 0.1);
				nsx = nsx + step * inc;
				nsx = (nsx < 0) ? 0 : Math.min(nsx, owner._twidth - owner._dwidth);
			}

if (owner._scrollX != nsx || owner._scrollY != nsy)
			{
				owner._scrollX = nsx;
				owner._scrollY = nsy;
				
				owner.updateThmbPos();
				
				// this._regHscrollThmb.css({left: owner._scrollX )
				
				me.do_scroll(direction);
			}
		}
	},
	
