	onScrollMouseClick: function(elem, ev, direction) {
		var owner = this;
		
		ev.stopPropagation();
		
		owner.endEdit();
		
		var nsx = owner._scrollX,
			nsy = owner._scrollY,
			inc = 0,
			step,
			__tw, __th,
			tpos,
			pageX = ev.pageX,
			pageY = ev.pageY,
			offset = (direction == "v") ? 
				owner._regVscrollThmb.offset() : 
				owner._regHscrollThmb.offset();
		
		tpos = owner.gl_pos(ev);
		pageX = tpos.pageX;
		pageY = tpos.pageY;
		
		if (direction == "v")
		{
			inc = (offset.top > pageY) ? -1 : 1;
			step = owner.thumbvheight;
			nsy += step * inc;
			__th = IG$.j$ext._h(owner._regVscroll);
			nsy = Math.min(__th - owner.thumbvheight, Math.max(0, nsy));
			if (owner._scrollY == nsy)
				return;
			owner._scrollY = nsy;
		}
		else
		{
			inc = (offset.left > pageX) ? -1 : 1;
			step = owner.thumbhwidth;
			nsx += step * inc;
			__tw = IG$.j$ext._w(owner._regHscroll);
			nsx = Math.min(__tw - owner.thumbhwidth, Math.max(0, nsx));
			if (owner._scrollX == nsx)
				return;
			owner._scrollX = nsx;
		}
		
		owner.updateThmbPos();
		owner.do_scroll(direction);
	},
	
	on_thumbTimer: function(direction) {
		var me = this,
			sm,
			qc,
			thumbsize;

		void 0;

		if (direction == "h")
		{
			thumbsize = Math.max(30, me.thumbhwidth);
			sm = me._scrollX * (me._rect.twidth - me._rect.cwidth) / (me._rect.cwidth - thumbsize);
			me._regData_hd.css({left: -sm});
			me._regData_og.css({left: -sm});
			return;
		}

		sm = me._scrollY / me.sv;
		if (sm > (me._theight - me._cheight))
		{
			me.fireEvent("scrollend", null);
		}
		
		qc = me.checkRequest();
		me.__scr = (qc.r == 2 ? 1 : 0);	

		if (qc.r == 2)
		{
			me.__scr_a = {
				nrow: qc.nrow,
				_scrollY: qc._scrollY
			};

			// me.fireEvent("scroll_request", qc.nrow);
			me.do_scroll("v", qc);
			return;
		}

		var drows = me.draw_data();
		me._clean_renderers([me.renderers.data_fixed, me.renderers.data], drows);
		me.sync_tables(2);
		me._update_sparkline();
		me.validate_scroll();
		void 0;
	},
	
	updateThmbPos: function() {
		var me = this,
			thumbsize = 30,
			_rect = me._rect,
			__tw, __th, __tw1, __th1;
		
		if (me.regh)
		{
			__tw = _rect.cwidth;
			__tw1 = Math.max(30, me.thumbhwidth);
			me._regHscrollThmb.css({left: Math.min(me._scrollX, __tw - __tw1)});
		}

		if (me.regv)
		{
			__th = _rect.cheight;
			__th1 = Math.max(30, me.thumbvheight);
			me._regVscrollThmb.css({top: Math.min(me._scrollY, __th - __th1)});
		}
	},
	
	setOffset: function(owner, mx, my, pgX, pgY, scr) {
		var me = this,
			_rect = owner._rect,
			nsx = owner._scrollX,
			nsy = owner._scrollY,
			__tw, __th,
			_regVscroll = me._regVscroll,
			__vh,
			__nsy,
			_nsx = nsx, _nsy = nsy,
			thumbsize;
		
		if (owner.sh < 1 && Math.abs(mx) > 5)
		{
			thumbsize = Math.max(30, owner.thumbhwidth);
			_nsx = Math.min(_rect.cwidth - thumbsize, Math.max(0, nsx + mx));
		}
		
		if (owner.sv < 1 && typeof(my) == "undefined")
		{
			thumbsize = Math.max(30, owner.thumbvheight);
			__vh = scr * owner.sv * 21;
			_nsy = Math.min(_rect.cheight - thumbsize, Math.max(0, owner._scrollY + __vh));
			
			if (_nsy < 0)
			{
				_nsy = 0;
			}
		}
		else if (owner.sv < 1 && Math.abs(my) > 5)
		{
			thumbsize = Math.max(30, owner.thumbvheight);
			_nsy = Math.min(_rect.cheight - thumbsize, Math.max(0, nsy + my));
		}

		if (_nsy != nsy)
		{
			var qc = me.checkRequest();
			me.__scr = (qc.r == 2 ? 1 : 0);	

			if (qc.r == 2)
			{
				me.__scr_a = {
					nrow: qc.nrow,
					_scrollY: qc._scrollY
				};
				// me.fireEvent("scroll_request", qc.nrow);
				owner.do_scroll("v", qc);
				return;
			}
		}
				
		if (_nsx != nsx || _nsy != nsy)
		{
			owner._scrollX = _nsx;
			owner._scrollY = _nsy;
			owner.updateThmbPos();
			if (_nsx != nsx)
			{
				owner.do_scroll("h");
			}
			
			if (_nsy != nsy)
			{
				owner.do_scroll("v");
			}
		}
	},
	
