	is_rendered: function(domObj) {
		var jdom = $(domObj)[0];
		if (jdom && ((jdom.nodeType != 1) || (jdom == document.body))) 
		{
			return true;
		}
		if (jdom && jdom.currentStyle && jdom.currentStyle["display"] != "none" && jdom.currentStyle["visibility"] != "hidden") 
		{
			return this.is_rendered(jdom.parentNode);
		} else if (jdom && window.getComputedStyle) {
			var cs = document.defaultView.getComputedStyle(jdom, null);
			if (cs.getPropertyValue("display") != "none" && cs.getPropertyValue("visibility") != "hidden") 
			{
				return this.is_rendered(jdom.parentNode);
			}
		}
		return false;
	},
	
	check_rendered: function(domObj) {
		var jdom = $(domObj)[0];
		var obj = domObj;
		if ((jdom.nodeType != 1) || (jdom == document.body)) 
		{
			return null;
		}
		if (jdom.currentStyle && (jdom.currentStyle["display"] == "none" || jdom.currentStyle["visibility"] == "hidden"))
		{
			return obj;
		} 
		else if (window.getComputedStyle) 
		{
			var cs = document.defaultView.getComputedStyle(jdom, null);
			if (cs.getPropertyValue("display") == "none" || cs.getPropertyValue("visibility") == "hidden") 
			{
				return obj;
			}
		}
		else
		{
			obj = this.check_rendered(jdom.parentNode);
			if (obj)
			{
				return obj;
			}
		}
		return obj;
	},
	
	browser: function() {
		var rv = -1; // Return value assumes failure.

		if (navigator.appName == 'Microsoft Internet Explorer')
		{
			var ua = navigator.userAgent;
			var re  = new RegExp("MSIE ([0-9]{1,}[\.0-9]{0,})");
			if (re.exec(ua))
				rv = parseFloat( RegExp.$1 );
		}
	
		return rv;
	}
