	rconfigFilterItem: function(params) {
		var me = this,
			pitem = params[0],
			rowIndex = params[1],
			filteritems = me.down("[name=filteritems]"),
			record = filteritems.store.data.items[rowIndex];
		
		$.each(pitem, function(n, m) {
			if (n == "id")
				return;
			
			record.set(n, m);
		});
	},
	
	removeFilterItem: function(rowIndex, colIndex) {
		var me = this,
			p1 = me.filter_items,
			filteritems = me.down("[name=filteritems]"),
			rec = filteritems.store.data.items[rowIndex],
			f_uid = rec.get("f_uid"),
			i,
			ps;
		
		filteritems.store.remove(rec);
		
		for (i=0; i < p1.length; i++)
		{
			ps = p1[i];
			if (ps.f_uid == f_uid)
			{
				if (ps.objtype == "button")
				{
					me.down("[name=showbutton]").setValue(false);
				}
				p1.splice(i, 1);
				break;
			}
		}
	},
	
