	gen_uid: function() {
		var me = this,
			m = {},
			i,
			filteritems = me.down("[name=filteritems]"),
			store = filteritems.getStore(),
			rec,
			uid;
			
		for (i=0; i < store.data.items.length; i++)
		{
			rec = store.data.items[i];
			m[rec.get("f_uid")] = 1;
		}
		
		uid = "f_" + (++me.f_uid);
		while (m[uid])
		{
			uid = "f_" + (++me.f_uid);
		}
		
		return uid;
	},
	
