	_btn_proc: function(btype, nvalue) {
		var me = this,
			p1 = me.filter_items,
			filteritems = me.down("[name=filteritems]"),
			hasbutton,
			buttonname,
			action;
			
		if (p1)
		{
			switch (btype)
			{
			case "showbutton":
				buttonname = "buttonname";
				action = "updateFilterValues";
				break;
			case "f_bx_enable":
				buttonname = "f_bx_name";
				action = "f_bx";
				break;
			}
			$.each(p1, function(i, p) {
				if (p.objtype == "button" && p.options.action == action)
				{
					if (!nvalue)
					{
						// remove button
						p1.splice(i, 1);
						$.each(filteritems.store.data.items, function(j, item) {
							if (item.data.f_uid == p.f_uid)
							{
								filteritems.store.remove(item);
								return false;
							}
						});
					}
					else
					{
						hasbutton = 1;
					}
					return false;
				}
			});
			
			if (!hasbutton && nvalue)
			{
				// add button
				var btn = {
					objtype: "button",
					f_uid: "f_" + (++me.f_uid),
					options: {
						text: me.down("[name=" + buttonname + "]").getValue(),
						action: action
					}
				};
				btn.title = "Button - " + btn.options.text;
				p1.push(btn);
				filteritems.store.add(btn);
			}
		}
	},
	
	_add_widget: function(objtype) {
		var me = this,
			grd = me.down("[name=filteritems]"),
			store = grd.getStore(),
			i,
			gnames = {},
			nname,
			n = 0,
			npf;
			
		for (i=0; i < store.data.items.length; i++)
		{
			gnames[store.data.items[i].get("name")] = 1;
		}
		
		nname = objtype + "_" + n;
		
		while (gnames[nname])
		{
			n++;
			nname = objtype + "_" + (n);
		}
		
		npf = {
			"name": nname, 
			"type": objtype, 
			"selected": false, 
			"operator": "",
			"title": "",
			"objtype": objtype,
			"f_uid": me.gen_uid()
		};
		
		me.filter_items.push(npf);
		
		store.add(npf);
	},
	
