IG$.sheetTWc = $s.extend($s.window, {

	width: 500,
	height: 520,
	layout: "fit",
	padding: ig$.padding,
	
	_init: function() {
		var me = this,
			dhtml = me.dhtml,	
			djs = me.djs,
			toptions = me.down("[name=toptions]"),
			controls = [];
		
		controls.push({
			xtype: "textfield",
			name: "id",
			fieldLabel: "Id",
			required: true
		});
		
		me.tsel = {};
			
		dhtml.parameters && me._add_ctrl(dhtml.parameters, controls);
		djs && djs.parameters && me._add_ctrl(djs.parameters, controls);
		
		$.each(controls, function(i, ctrl) {
			toptions.add(ctrl);
		});
	},
	
	_add_ctrl: function(params, controls) {
		var me = this,
			rop = me.rop;
		
		$.each(params, function(i, param) {
			var ctrl = {
				xtype: "textfield",
				fieldLabel: param.name,
				name: param.name,
				required: param.required
			};
			
			if (param.xtype == "bo_selector")
			{
				me._ukey = me._ukey || 0;
				var k = "ign_mitem_" + (me._ukey++);
				ctrl.xtype = "fieldcontainer";
				ctrl.layout = {
					type: "hbox",
					align: "stretch"
				};
				ctrl.items = [
					{
						xtype: "textfield",
						flex: 1,
						name: k,
						emptyText: IRm$.r1("M_SEL_ITEM"),
						required: true
					},
					{
						xtype: "button",
						iconCls: "icon-toolbar-search",
						tooltip: IRm$.r1("B_SEARCH"),
						handler: function() {
							if (rop && rop.cube_objects && rop.cube_objects.length)
							{
								var dlgitemsel = new IG$.metaSelectDlg({
									instance: me.instance,
									multiselect: 0,
									visibleItems: "userdb;table;dataset;inlineview;metric;custommetric",
									tree_options: {
										cubebrowse: true,
										rootuid: rop.cube_objects[0].uid
									},
									callback: new IG$.callBackObj(me, function(fitem) {
										me.tsel[param.name] = fitem;
										me.down("[name=" + k + "]").setValue(fitem.name);
									})
								});
								IG$.checkLogin(me, dlgitemsel);
							}
						},
						scope: this
					}
				];
			}
			else if (param.xtype == "combobox")
			{
				ctrl.xtype = param.xtype;
				ctrl.displayField = "name";
				ctrl.valueField = "value";
				ctrl.store = {
					data: param.data
				};
			}
			else
			{
				ctrl.xtype = param.xtype || "textfield";
			}
			
			controls.push(ctrl);
		});
	},
	
	_confirm: function(rec) {
		var me = this,
			toptions = me.down("[name=toptions]"),
			tsel,
			thtml,
			tjs;
			
		if (toptions.getAllValues(me.tsel))
			return;
			
		tsel = me.tsel;
		
		thtml = me._proc(me.dhtml.html, tsel);
		if (me.djs)
		{
			tjs = me._proc(me.djs.jscript, tsel);
		}
		me.callback && me.callback.execute(thtml, tjs);
		me.close();
	},
	
	_proc: function(tarr, tsel) {
		var r = [];
		
		if (tarr && tarr.length)
		{
			$.each(tarr, function(i, c) {
				var s = c,
					n1 = s.indexOf("{"),
					n2;
				
				while (n1 > -1)
				{
					n2 = s.indexOf("}", n1);
					
					if (n2 > -1)
					{
						var mm = s.substring(n1 + 1, n2);
						
						if (mm.indexOf(".") > -1)
						{
							var mm1 = mm.substring(0, mm.indexOf(".")),
								mm2 = mm.substring(mm.indexOf(".") + 1);
								
							if (tsel[mm1])
							{
								s = s.substring(0, n1) + (tsel[mm1][mm2] || "") + s.substring(n2 + 1);
							}
						}
						else if (tsel[mm])
						{
							s = s.substring(0, n1) + tsel[mm] + s.substring(n2 + 1);
						}
					}
					else
					{
						break;
					}
					
					n1 = s.indexOf("{", n1 + 1);
				}
				
				r.push(s);
			});
		}
		
		return r.join("\n");
	},
	
	initComponent: function(){
		var me = this;
		
		$s.apply(me, {
			title: "Option Values",
			items: [
				{
					xtype: "panel",
					padding: ig$.padding,
					layout: {
						type: "vbox",
						align: "stretch"
					},
					items: [
						{
							xtype: "fieldset",
							title: "Option Values",
							name: "toptions",
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								
							]
						}
					]
				}
			],
			buttons: [
				"->",
				{
					xtype: "button",
					text: IRm$.r1("B_CONFIRM"),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				},
				{
					xtype: "button",
					text: IRm$.r1("B_CANCEL"),
					handler: function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(tobj) {
					tobj._init();
				}
			}
		});
		
		IG$.sheetTWc.superclass.initComponent.call(this);
	}
});

