IG$.wseopt = $s.extend($s.window, {
	
	modal: true,
	region:'center',
	layout: "fit",
	
	closable: false,
	resizable:false,
	width: 500,
	height: 450,	
	
	callback: null,
	
	init_f: function() {
		var me = this,
			_rop = me.reportoption._mc,
			opt = me.sheetoption,
			optmodel = opt ? opt.model : null,
			export_option = _rop ? _rop.export_option : null,
			sheet_toolbar = ig$.sheet_toolbar$,
			tb_prt_i = me.down("[name=tb_prt_i]"),
			tb_prt_ival, rec, tb_prt_sval, n,
			i;

		if (optmodel.objtype == "FILTER")
		{
			tb_prt_i.store.loadData([]);
		}
		
		if (export_option)
		{
			$.each(["excel", "pdf", "csv"], function(i, t) {
				if (export_option["u_" + t])
				{
					tb_prt_i.store.add({
						showitem: false,
						name: "Builtin (" + t + ")",
						key: t
					});
				}
			});
			
			if (export_option.u_office && export_option.otmpl)
			{
				$.each(export_option.otmpl, function(i, p) {
					tb_prt_i.store.add({
						showitem: false,
						name: "Office " + (p.export_type ? "-" + p.export_type + " " : "") + "(" + p.description + ": " + p.name + ")",
						key: "office_" + i
					});
				});
			}
			
			if (export_option.u_jasper && export_option.jasper && export_option.jasper.jasper_template)
			{
				$.each(["pdf", "rtf", "ppt", "excel", "xlsx", "docx", "html", "xml"], function(i, p) {
					if (export_option.jasper[p + "_output"] == "T")
					{
						tb_prt_i.store.add({
							showitem: false,
							name: "JASPER (" + p.toUpperCase() + ")",
							key: "jasper_" + p
						});
					}
				});
			}
		}
		
		if (sheet_toolbar && sheet_toolbar.length)
		{
			for (i=0; i < sheet_toolbar.length; i++)
			{
				tb_prt_i.store.add({
					showitem: false,
					name: sheet_toolbar[i].name,
					key: sheet_toolbar[i].key
				});
			}
		}

		tb_prt_ival = (optmodel.tb_prt_i ? ";" + optmodel.tb_prt_i + ";" : "");
		tb_prt_sval = (optmodel.tb_prt_s ? optmodel.tb_prt_s : "").split(";");
		
		n = 0;

		for (i=0; i < tb_prt_i.store.data.items.length; i++)
		{
			rec = tb_prt_i.store.data.items[i];

			if (tb_prt_ival && tb_prt_ival.indexOf(";" + rec.get("key") + ";") > -1)
			{
				rec.set("style", tb_prt_sval[n]);
				rec.set("showitem", true);
				n++;
			}
			else
			{
				rec.set("showitem", false);
			}
		}
	},
	
	_confirm: function() {
		var me = this,
			tb_prt_i = me.down("[name=tb_prt_i]"),
			_rop = me.reportoption._mc,
			opt = me.sheetoption,
			store_data,
			optmodel,
			n = 0, i,
			rec;

		optmodel = opt.model = opt.model || {};

		optmodel.tb_prt_i = "";
		optmodel.tb_prt_s = "";

		store_data = tb_prt_i.store.data.items;

		for (i=0; i < store_data.length; i++)
		{
			rec = store_data[i];

			if (rec.get("showitem") == true)
			{
				optmodel.tb_prt_i += (optmodel.tb_prt_i ? ";" : "") + rec.get("key");
				optmodel.tb_prt_s += (n > 0 ? ";" : "") + (rec.get("style") || "");
				n++;
			}
		}

		me.close();
	},
	
	initComponent: function() {
		var me = this,
			lwidth = 160,
			c_dt = [
				{name: "Equal", value: "EQ"},
				{name: "Not Equal", value: "NE"},
				{name: "In", value: "IN"},
				{name: "Greater or Equal", value: "GTE"},
				{name: "Less or Equal", value: "LTE"},
				{name: "Greater", value: "GT"},
				{name: "Lesser", value: "LT"},
				{name: "Like", value: "LIKE"},
				{name: "Between", value: "BETWEEN"},
				{name: "Not In", value: "NOTIN"}
			],
			i, c_dtm = {},
			c_ds = [],
			bcss = ig$.button_css;
			
		for (i=0; i < c_dt.length; i++)
		{
			c_dtm[c_dt[i].value] = c_dt[i].name;
		}
		
		if (bcss && bcss.length)
		{
			c_ds.push({name: IRm$.r1("B_SELECT"), value: ""});
			
			for (i=0; i < bcss.length; i++)
			{
				c_ds.push(bcss[i]);
			}
		}
		else
		{
			c_ds = [
				{name: IRm$.r1("B_SELECT"), value: ""},
				{name: "pdf_1", value: "exp_pdf_1"},
				{name: "word_1", value: "exp_word_1"},
				{name: "word_2", value: "exp_word_2"},
				{name: "word_3", value: "exp_word_3"},
				{name: "word_4", value: "exp_word_4"},
				{name: "word_5", value: "exp_word_5"},
				{name: "word_6", value: "exp_word_6"},
				{name: "word_7", value: "exp_word_7"},
				{name: "ppt_1", value: "exp_ppt_1"},
				{name: "ppt_2", value: "exp_ppt_2"},
				{name: "ppt_3", value: "exp_ppt_3"},
				{name: "ppt_4", value: "exp_ppt_4"},
				{name: "excel_1", value: "exp_excel_1"},
				{name: "excel_2", value: "exp_excel_2"},
				{name: "csv", value: "idv-dk-btn-e-csv"},
				{name: "office", value: "idv-dk-btn-e-xls"}
			];
		}

		$s.apply(this, {
			title: IRm$.r1("L_TB_PRT"),
			
			items: [
				{
					xtype: "panel",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					flex: 1,
					bodyBorder: false,
					padding: ig$.padding,
					items: [
						{
							xtype: "fieldset",
							title: IRm$.r1("L_TB_PRT_T"),
							flex: 1,
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "gridpanel",
									name: "tb_prt_i",
									flex: 1,
									store: {
										xtype: "store",
										fields: [
											"name", "showitem", "key", "style"
										],
										data: [
											// {showitem: false, name: "Excel", key: "excel"},
											// {showitem: false, name: "PDF", key: "pdf"},
											// {showitem: false, name: "CSV", key: "csv"}
										]
									},
									plugins: {
										ptype: "cellediting",
										clicksToEdit: true
									},
									columns: [
										{
											text: IRm$.r1("B_ENABLED"),
											xtype: "checkcolumn",
											dataIndex: "showitem",
											listeners: {
												checkchange: function(tobj, rowindex, checked, eopts) {
													if (checked)
													{
														this.down("[name=tb_prt]").setValue(true);
													}
												},
												scope: this
											}
										},
										{
											text: IRm$.r1("B_NAME"),
											flex: 1,
											dataIndex: "name"
										},
										{
											text: IRm$.r1("B_STYLE"),
											flex: 1,
											dataIndex: "style",
											editor: {
												xtype: "combobox",
												queryMode: "local",
												displayField: "name",
												valueField: "value",
												editable: false,
												autoSelect: true,
												store: {
													xtype: "store",
													fields: ["name", "value"],
													data: c_ds
												}
											}
										}
									]
								}
							]
						}
					]
				}
			],
			buttons:[
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, 
				{
					text: IRm$.r1('B_CANCEL'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(ui) {
					var panel = this;
					panel.init_f();
				}
			}
		});
		
		IG$.wseopt.superclass.initComponent.apply(this, arguments);
	}
});