IG$.n$navTreeCom = $s.extend($s.treepanel, {
	xtype: "treepanel",
	customMenu: null,
	
	enabledrag: true,
	
	ntritem: null,
	ntrnode: null,
	ntrseq: 0,
	border: 0,
	
	tooltip: false,
	
	region: "west",
	split:true,
	header: false,
	collapsible: true,
	rootVisible:true,
	lines:false,
	animCollapse:false,
	animate: true,
	collapseMode:"mini",
	
	collapseFirst:false,
	singleExpand: false,
	
	selectedNode: [],
	
	navigateTree: function(dt) {
		var me = this,
			root = me.getRootNode(),
			rpath = root.get("nodepath");
		
		me.ntritem = dt;
		me.ntrnode = root;
		me.ntrseq = 1;
		
		if (rpath && dt.nodepath.indexOf(rpath) > -1)
		{
			me.ntrseq = rpath.split("/").length;
		}
		
		me.navigateTreeOpen();
	},
	
	navigateTreeOpen: function() {
		var me = this,
			cpath = me.ntritem.nodepath || me.ntritem,
			cp = cpath.split("/"),
			cname, i, node,
			seq = me.ntrseq,
			pnode = me.ntrnode;
		
		if (pnode && cp.length > seq)
		{
			cname = cp[seq];
			
			me.getSelectionModel().select(pnode);
			
			for (i=0; i < pnode.childNodes.length; i++)
			{
				node = pnode.childNodes[i];
				if (node.data.name == cname)
				{
					if (node.isLeaf() == false)
					{
						me.ntrnode = node;
						me.ntrseq++;
						
						me.getSelectionModel().select(node);
						node.expand(false, me.navigateTreeOpen, me);
					}
					else
					{
						me.ntrnode = null;
						me.ntrseq = 0;
						
						me.getSelectionModel().select(node);
					}
					break;
				}
			}
		}
	},
	
	setFilter: function(fitem) {
		var me = this,
			rnode = me.getRootNode();
		me._fitem = fitem;
		
		me._updateFilter(rnode, me._fitem);
	},
	
	_updateFilter: function(rnode, fitem, force) {
		var me = this,
			i, ltype,
			rec;
		if (rnode.childNodes && rnode.childNodes.length)
		{
			for (i=0; i < rnode.childNodes.length; i++)
			{
				rec = rnode.childNodes[i];
				ltype = rec.data.ltype;
				if (!ltype)
				{
					ltype = rec.data.ltype = rec.data.type.toLowerCase()
				}
				if (ltype == "folder")
				{
					me._updateFilter(rec, fitem, force);
				}
				else if (ltype == "table" || ltype == "inlineview")
				{
					if (!fitem || (fitem && fitem[rec.data.uid]))
					{
						rec.set("disabled", false);
					}
					else
					{
						rec.set("disabled", true);
					}
					
					me._updateFilter(rec, fitem, rec.get("disabled"));
				}
				else
				{
					rec.set("disabled", force);
				}
			}
		}
	},
	
	_createMetaObject: IG$._createMetaObject,
	r_createMetaObject: IG$.r_createMetaObject,
	_renameMetaObject: IG$._renameMetaObject,
	r_renameMetaObject: IG$.r_renameMetaObject,
	
	deleteMetaObject: IG$.deleteMetaObject,
	rdeleteMetaObject: IG$.rdeleteMetaObject,
	
	editMeta: IG$.editMeta,
	
	raiseCustomEvent: function(eventname, cmd, record) {
		this.fireEvent(eventname, cmd, record);
	},
	
	moveSelItems: function() {
		var me = this,
			i,
			address = {},
			itemcnt = 0,
			item,
			req,
			cpath,
			record,
			mpath;
			
		if (me.selectedNode.length > 0)
		{
			var tree_options = {};
			
			for (i=0; i < me.selectedNode.length; i++)
			{
				item = me.selectedNode[i];
				if (item.data.type.toLowerCase() == "help")
				{
					treeoptions.rootuid = me.rootuid;
				}
				mpath = item.data.nodepath.substring(0, item.data.nodepath.lastIndexOf("/"));
				
				if (cpath != mpath)
				{
					itemcnt = 0;
					IG$.ShowError(IRm$.r1("E_"), me); // "One subfolder content is allowed to move.", me);
					break;
				} 
				else if (item.data.manage || item.data.writable)
				{
					address.push({
						uid: item.data.uid
					});
					itemcnt++;
				}
				else
				{
					itemcnt = 0;
					IG$.ShowError(IRm$.r1("E_PRIV_ERR"), me); // "Privilege error on content", me);
					break;
				}
			}
			
			if (itemcnt > 0)
			{
				var dlgitemsel = new IG$.metaSelectDlg({
					instance: me.instance,
					mode: "select",
					targetobj: "folder",
					visibleItems: "folder",
					tree_options: tree_options,
					callback: new IG$.callBackObj(me, me.rmoveSelItems, [address, record])
				});
				IG$.checkLogin(me, dlgitemsel);
			}
		}
	},
	
	rmoveSelItems: function(item, params) {
		var req,
			address = params[0],
			record = params[1],
			me = this;
		
		req = new IG$._rpc$();
		req.init(me, 
			{
				ack: "helpcontent",
				payload: address,
				mbody: {option: "move", target: item.uid}
			}, me, me.r_moveSelItems, null, record);
		req.send();
	},
	
	r_moveSelItems: function(xdoc, record) {
		var me = this;
		me.refreshNode(record);
		me.selectedNode = [];
		IG$.alertmsg(ig$.appname, "Moved items successfully", null, me, 0, "success");
	},
	
	removeSelItems: function() {
		var me = this,
			i,
			address = {},
			itemcnt = 0,
			item,
			req;
		if (me.selectedNode.length > 0)
		{
			for (i=0; i < me.selectedNode.length; i++)
			{
				item = me.selectedNode[i];
				if (item.data.manage || item.data.writable)
				{
					address.push({
						uid: item.data.uid
					});
					itemcnt++;
				}
				else
				{
					itemcnt = 0;
					IG$.ShowError(IRm$.r1("E_PRIV_ERR"), me); // "Privilege error on content", me);
					break;
				}
			}
			
			if (itemcnt > 0)
			{
				req = new IG$._rpc$();
				req.init(me, 
					{
						ack: "batchcontent",
						payload: address,
						mbody: {option: "delete"}
					}, me, me.rdeleteMetaObject, null);
				req.send();
			}
		}
	},
	
	
	
	filterTree: function(t, e){
		
	},
	
	refreshTree: function(unode) {
		var me = this,
			values = {},
			rnode = unode || me.getRootNode(),
			cobj;
		
		me._expandedNodes = {};
		
		rnode.dirty = true;
		rnode.data.loaded = false;
		rnode.data.expanded = false;
		
		// rnode.removeAll(true);
		while (rnode.firstChild)
		{
			if (rnode.childNodes && rnode.firstChild.isExpanded())
			{
				me._expandedNodes[rnode.firstChild.get("uid")] = 1;
				me._updateExpanded(rnode.firstChild, me._expandedNodes);
			}
			rnode.removeChild(rnode.firstChild);
		}
		
		if (me._rootitems)
		{
			cobj = me._rootitems;
			for (i=0; i < cobj.length; i++)
			{
				delete cobj[i]["id"];
				delete cobj[i]["open"];
				
				cobj[i].leaf = false;
				cobj[i].children = [
					{
						type: "load",
						name: "Loading..."
					}
				];
				
				rnode.appendChild(cobj[i]);
			}
		}
		else
		{
			rnode.appendChild({
				open: false,
				type: "load",
				name: "Loading..."
			});
			rnode.collapse();
		}
		
		rnode.expand();
	},
	
	_updateExpanded: function(rnode, expandedNodes) {
		var i,
			me = this,
			snode;
		
		if (rnode.childNodes)
		{
			for (i=0; i < rnode.childNodes.length; i++)
			{
				snode = rnode.childNodes[i];
				
				if (snode.childNodes && snode.childNodes.length && snode.isExpanded())
				{
					expandedNodes[snode.get("uid")] = 1;
					
					me._updateExpanded(snode, expandedNodes);
				}
			}
		}
	},
		
	refreshNode: function(node) {
		var unode = node,
			me = this;
		if (node.isLeaf() == true)
		{
			unode = node.parentNode;
		}
		
		me.refreshTree(unode);
	},
	
	refTopNode: function() {
		this.selectedNode = [];
		var rnode = this.getRootNode();
		
		this.setPosition(0, 0);
		this.getSelectionModel().select(rnode);
		rnode.dirty = true;
		rnode.data.loaded = false;
		rnode.data.expanded = false;
		
		while (rnode.firstChild)
		{
			rnode.removeChild(rnode.firstChild);
		}
		rnode.expand(false);
	},
	
	appendRootWS: function(value) {
		var root = this.getRootNode(),
			Model = this.store.model,
			i,
			record,
			bfound = false;
		
		for (i=0; i < root.childNodes.length; i++)
		{
			if (root.childNodes[i].data.uid == value.uid)
			{
				bfound = true;
				break;
			}
		}
		
		if (bfound == false)
		{
			record = new Model(value);
			record.raw = value;
			root.appendChild(record);
		}
	},
	
	pasteMetaObject: function(record) {
		var me = this,
			req = new IG$._rpc$();
		
		req.init(me, 
			{
				ack: "writecontent",
				payload: {pid: record.get("uid"), address: IG$.clipboard.uid},
				mbody: {option: "copy"}
			}, me, me.rpasteMetaObject, null, record);
		req.send();
	},
	
	rpasteMetaObject: function(xdoc, record) {
		this.refreshNode(record);
	},
	
	prepareCustomMenu: IG$.prepareCustomMenu,
	
	manageFolder: function(rec) {
		var me = this,
			dlg = new IG$.dlgFolderMgr({
				instance: me.instance,
				root: {
					uid: rec.get("uid"),
					name: rec.get("name"),
					type: rec.get("type")
				}
			});
		IG$.checkLogin(this, dlg);
	},
	
	exportMeta: function(meta) {
		var me = this,		
			dlg = new IG$.metaExpDlg({
				instance: me.instance,
				meta: meta
			});
		
		/*
		if (ig$.$l_ > 5)
		{
			me.exportMeta_exec(meta);
		}
		else
		{
		*/
			IG$.checkLogin(this, dlg);
		// }
	},
	
	exportMeta_exec: function(meta) {
		var me = this,
			req = new IG$._rpc$(),
			opt = {output: "file"};
		
		opt.opt_dependants = "T";
		opt.opt_security = "T";
		opt.opt_owner_info = "T";
		
		IG$.confirmMessages(IRm$.r1("T_EXP_MC"), IRm$.r1("T_EXP_MC_Q"), function(dlg) {
			if (meta && dlg == "yes")
			{
				req.init(me, 
					{
						ack: "content",
						payload: {uid: meta.uid, nodepath: meta.nodepath, name: meta.name, type: meta.type},
						mbody: opt
					}, me, function(jdoc) {
						var fpath, filename;
						
						if (jdoc)
						{
							fpath = jdoc.luid;
							filename = jdoc.filename;
							
							IG$.alertmsg(ig$.appname, IRm$.r1('M_SAVED'), null, null, 0, "success");
							
							if (fpath && filename)
							{
								$.download(ig$.servlet + "/download", [
									{name: "ack", value: "download"},
									{name: "_mts_", value: IG$._g$a || ""},
									{name: "payload", value: fpath},
									{name: "mbody", value: filename},
									{name: "session_key", value: (window.use_session_key ? ig$._session_key || "empty" : "")}
								], "POST");
							}
						}
					}, null);
				req.send();
			}
		}, me, me);
	},
	
	initComponent: function(){
		var me = this,
			columns = []; 
		
		if (me.tree_options)
		{
			$s.apply(this, me.tree_options);
		}
		
		if (me._meta_move == true) //  && ig$.$l_ < 5)
		{
			me.beforedrop_exec = new IG$.callBackObj(me, function(tobj, node, data, dropRec, dropPosition, dropFunction) {
				var me = this,
					rootnode = me.getRootNode(),
					status = false;
				
				if (data && data.view && data.view == me && data.records && data.records.length)
				{
					// self-drag&drop
					IG$.confirmMessages(ig$.appname, IRm$.r1("M_CONFIRM_DROP_FILE"), function(e) {
						if (e == "yes" && dropRec && (dropRec.get("writable") == true || dropRec.get("type") == "Root"))
						{
							var dtype = dropRec.get("type"),
								bsuccess = 1,
								req,
								address = [],
								body = {option: "move", target: dtype == "Root" ? "/" : dropRec.get("uid")};
							
							if (dtype && (dtype == "Folder" || dtype == "Bobject" || dtype == "Root"))
							{
								$.each(data.records, function(i, rec){
									var rtype = rec.get("type"),
										rtype = rtype ? rtype.toLowerCase() : null;
									
									if (rtype == "folder" || rtype == "report" || rtype == "bobject")
									{
										if (dtype == "Root")
										{
											
										}
										else if (rec.get("pid") == dropRec.get("uid"))
										{
											bsuccess = 0;
											return false;
										}
									}
									else if ((rtype == "table" || rtype == "inlineview" || rtype == "cubemodel") && (dtype == "Bobject" || dtype == "Folder"))
									{
									}
									else if (rtype == "root")
									{
										bsuccess = 0;
										return false;
									}
									else if (dtype == "Folder" && (rtype == "datemetric" || rtype == "measure" || rtype == "metric" || rtype == "chartmeasure"))
									{
									}
									else if (rec.get("is_priv") || rec.get("is_dept"))
									{
										bsuccess = 0;
										return false;
									}
									else
									{
										bsuccess = 0;
										return false;
									}
									
									if (bsuccess)
									{
										address.push({uid: rec.get("uid")});
									}
								});
								
								if (bsuccess == 0)
								{
									status = false;
								}
								else if (address.length)
								{
									status = true;
									req = new IG$._rpc$();
									req.init(me, 
										{
											ack: "helpcontent",
											payload: address,
											mbody: body
										}, me, function(jdoc) {
											$.each(data.records, function(i, record) {
												record.parentNode.removeChild(record);
											});
											
											me.refreshNode(dropRec);
										}, null, null);
									req.send();
								}
							}
						}
					});
				}
				
				return status;
			});
		}
		
		columns = [
			{
				xtype: "treecolumn", //this is so we know which column will show the tree
				text: IRm$.r1("B_NAME"),
				flex: 2,
				sortable: false,
				dataIndex: "name",
				renderer: function(value, metadata, record) {
					var mstyle = "",
						mname = record.get("locale_name") || record.get("name"),
						type = record.get("type") || "",
						ltitle = mname;
					
					if (record.get("local_name") && record.get("local_name") != record.get("name"))
					{
						ltitle += " (" + record.get("name") + ")";
					}
					if (type.toLowerCase() == "metric" && record.data.attributes && record.data.attributes.attrb3)
					{
						if (ltitle[ltitle.length-1] == ')')
						{
							ltitle = ltitle.substring(0, ltitle.length-1);
							ltitle += " => " + record.data.attributes.attrb3 + ")";
						}
						else
						{
							ltitle += " => " + record.data.attributes.attrb3;
						}
					}

					ltitle += "\n ===> " + (record.get("nodepath") || "unknown");
					
					// ltitle += " * owner: " + record.get("")
					
					if (record.get("scid"))
					{
						mstyle = "igc-subscribed";
					}
					
					if (record.data.disabled)
					{
						mstyle += " igc-disabled";
					}
					
					type = type.toLowerCase();
					
					return "<span class='" + mstyle + "' " + (type == "report" || type == "dashboard" ? " amp-bind='" + type + ":" + record.get("uid") + "'" : "") + " title='" + IG$.hEE(ltitle) + "'>" + IG$.hEE(mname) + "</span>";
				}
			}
		];
		
		tbarobj = [
			{
				iconCls: "icon-refresh",
				tooltip: IRm$.r1("L_REFRESH"),
				handler: function() {
					var me = this;
					me.refTopNode();
				},
				scope: this
			}
		];
		
		$s.apply(this, {
			enableDragDrop: true,
			enableDD: true,
			useArrows: true,
			ddGroup: "_I$RD_G_",
			hideHeaders: true,
			hiddenPkgs: [],
			columns: columns,
			
			store: {
				xtype: "treestore",
				fields: [
					"uid", "nodepath", "address", "description", "manage", "memo", "name", "type", "writable", "lname", "locale", "is_sub"
				]
			},
			
			customMenu: new $s.menu({
				instance: me.instance,
				items: []
			}),
			selModel: {
				selection: "treemodel",
				mode: "MULTI"
			},
			viewConfig: me.enabledrag ? {
				plugins: {
					ptype: "gridviewdragdrop",
					dragGroup: "_I$RD_G_"
				},
				listeners: {
					beforedrop: function(node, data, dropRec, dropPosition, dropFunction) {
						var me = this,
							sview = data.view,
							records = data.records,
							status = false;
							
						if (me.panel && me.panel.beforedrop_exec)
						{
							status = me.panel.beforedrop_exec.execute(me, node, data, dropRec, dropPosition, dropFunction);
						}
							
						return status;
					},
					drop: function(node, data, dropRec, dropPosition) {
						var dropOn = dropRec ? " " + dropPosition + " " + dropRec.get("name") : " on empty view";
					}
				}
			} : null,
			
			listeners: {
				afterrender: function(tobj) {
					var rnode, root = {
						name: tobj.rootname || IRm$.r1("B_WORKSPACE"),
						expanded: true,
						address: "/",
						type: "Root",
						uid: tobj.rootuid || "",
						children: [
							{
								type: "load",
								name: "Loading..."
							}
						]
					};
					
					me.__loaded = 1;
					
					if (me.body && me.body.dom)
					{
						$(me.body.dom)
							.mousemove(function(e) {
								var c = e.target;
								
								if (c.getAttribute && c.getAttribute("amp-bind"))
								{
									var bdata = c.getAttribute("amp-bind");
									IG$._scrshot(c, bdata, true);
								}
								else
								{
									IG$._scrshot(c, null, false);
								}
							})
							.mouseleave(function(e) {
								var c = e.target;
								IG$._scrshot(c, null, false, true);
							});
					}
					
					if (me.rootuid == "none")
						return;

					setTimeout(function() {
						rnode = tobj.setRootNode(root);
						rnode.expand();
						
						if (me.initpath)
						{
							me.navigateTree(me.initpath);
						}
					}, 20);
				},
				beforeitemcontextmenu: function(view, record, item, index, e) {
					e.stopEvent();
					
					var me = this,
						x = e.pageX,
						y = e.pageY,
						
						t = e.getTarget();
						
					if (me.nav_options && me.nav_options.context_menu === false)
						return;
						
					var mvisible = me.prepareCustomMenu(record, me.btype);
					
					if (mvisible == true)
					{
						me.customMenu.showBy(t);
					}
					
					return false;
				},
				
				itemclick: function(view, record, item, index, e) {
					var me = this,
						bproc = false,
						data = record.data,
						mainPanel = me.mainPanel;
					
					if (e.target.nodeName == "INPUT")
						return;
					
					if (me.custom_click_func)
					{
						bproc = me.custom_click_func.execute(record, data);
					}
					
					me.gridupdate && me.gridupdate.execute(record);
					
					if (bproc == false)
					{
						var typename = data.type.toLowerCase(),
							itemname = data.name,
							itemaddr = data.nodepath,
							itemuid = data.uid,
							writable = (data.writable || data.manage) ? true : false,
							manageable = (data.manage) ? true : false,
							issubcube = data.issubcube;
						
						if (typename == "igccustom") {
							var m = window.igc_custom_menus.menuitems[itemuid];
							
							if (m && m.handler)
							{
								m.handler.call(window, m);
							}
						}
						else if (record.isLeaf() == true) {
							e && e.stopEvent && e.stopEvent();
							
							if (mainPanel)
							{
								mainPanel.navigateApp(itemuid, typename, itemname, itemaddr, true, writable);
							}
						}
					}
				},
				
				itemdblclick: function(tobj, record, item, index, e, eopts) {
					var me = this;
					
					e.stopPropagation();
					
					if (me.custDblClickFunc)
					{
						bproc = me.custDblClickFunc.execute(record);
					}
					
					me.gridupdate && me.gridupdate.execute(record);
				},
				
				beforeitemexpand: function(node, eopts) {
					var me = this,
						ltype = node.get("type"),
						mtype,
						luid = node.get("uid"),
						bproc;
					
					if (me.custom_expand_func)
					{
						bproc = me.custom_expand_func.execute(node);
						
						if (bproc)
							return;
					}
						
					if (node.isRoot())
					{
						if (!(node.childNodes.length > 0 && node.childNodes[0].get("type") == "load"))
						{
							return;
						}
						
						if (me.rootuid && me.rootuid != "none")
						{
							addr = {uid: me.rootuid};
						}
						else if (luid && luid.length > 0)
						{
							addr = {uid: luid};
						}
						else
						{
							addr = {uid: "/", type: "Folder"};
						}
					}
					else
					{
						addr = {uid: luid};
						
						if (!(node.childNodes.length > 0 && node.childNodes[0].get("type") == "load"))
						{
							return;
						}
					}
					
					var req = new IG$._rpc$(),
						_visibleItems = me._visibleItems,
						i,
						vitem = !_visibleItems && me.visibleItems ? me.visibleItems.split(";") : null;
						
					if (!_visibleItems && vitem && vitem.length)
					{
						for (i=0; i < vitem.length; i++)
						{
							if (vitem[i])
							{
								if (!_visibleItems)
								{
									_visibleItems = {};
								}
								
								_visibleItems[vitem[i]] = 1;
							}
						}
						
						me._visibleItems = _visibleItems;
					}
					
					node.removeAll();
					
					var req_handler = function(jdoc) {
						var nodes = jdoc ? jdoc.children : null,
							i, p, typename, memo,
							ishidden,
							dt = [];
						
						if (node.isRoot() && jdoc.nodepath != "/")
						{
							node.set("name", jdoc.name);
							node.set("type", jdoc.type);
							node.set("nodepath", jdoc.nodepath);
							node.set("writable", jdoc.writable);
						}
						
						if (luid == "~/" || luid == "!/")
						{
							node.set("uid", jdoc.uid);
							node.set("type", jdoc.type);
							node.set("nodepath", jdoc.nodepath);
							node.set("writable", jdoc.writable);
						}
						
						if (nodes)
						{
							for (i=0; i < nodes.length; i++)
							{
								p = nodes[i];
								p.text = p.name;
								p.address = p.uid;
								
								typename = p.type.toLowerCase();
								memo = p.memo ? p.memo.toLowerCase() : null;
								
								ishidden = (!_visibleItems || (_visibleItems && _visibleItems[typename])) ? 0 : 1;
								
								if (ishidden && (typename == "link" && p.rawtype && _visibleItems && _visibleItems[p.rawtype.toLowerCase()]))
								{
									ishidden = 0;
								}
								
								if (ishidden && me.cubebrowse && p.is_sub && (typename == "metric" || typename == "datemetric"))
								{
									ishidden = false;
								}
								
								if (!ishidden && me.hiddenItems && me.hiddenItems[typename])
								{
									ishidden = true;
								}
								
								if (ishidden)
									continue;
								
								if ((p.type == "Dimension" || p.type == "Metric") && p.attributes && p.attributes.attrb4)
								{
									p.datatype = IG$.get_datatype(p.attributes.attrb4);
								}
									
								if (IG$.testVal("metrics|table|inlineview|folder|rfolder|datemetric|javapackage|dataset|userdb", typename) == true)
								{
									if (IG$.testVal("table|inlineview", typename))
									{
										if (me._fitem && !me._fitem[p.uid])
										{
											p.disabled = true;
										}
									}
									p.leaf = false;
								}
								else
								{
									if (typename == "link" && p.rawtype.toLowerCase() == "cubemodel")
									{
										p.leaf = false;
									}
									else
									{
										p.leaf = true;
										p.allowDrag = true;
										p.disabled = node.data.disabled;
									}
								}
								
								if (p.leaf && p.is_sub && typename == "metric")
								{
									p.leaf = false;
								}
								
								if (p.children)
								{
									IG$.sortMeta(p.children);
								}
								
								if (!p.leaf && !p.children)
								{
									p.loaded = false;
									p.expanded = false;
									
									p.children = [
										{
											type: "load",
											name: "Wait while get data"
										}
									];
								}
								
								p.iconCls = IG$.get_metatype_icon(typename, p);
								dt.push(p);
							}
						}
						
						IG$.sortMeta(dt);
						
						if (node.isRoot() && jdoc.nodepath == "/")
						{
							if (ig$.features["ig_m_prv_ws"] === false)
							{
								dt.push({
									name: IRm$.r1("B_PRIV_FLD"),
									expanded: false,
									address: "~/",
									type: "Folder",
									is_priv: true,
									writable: true,
									uid: "~/",
									children: [
										{
											type: "load",
											name: "Loading..."
										}
									]
								});
							}
							
							if (ig$.features["ig_m_team_ws"] === false)
							{
								dt.push({
									name: IRm$.r1("B_PUB_FLD"),
									expanded: false,
									address: "!/",
									type: "Folder",
									writable: true,
									is_dept: true,
									uid: "!/",
									children: [
										{
											type: "load",
											name: "Loading..."
										}
									]
								});
							}
						}
						
						if (me.gridupdate)
						{
							for (i=dt.length-1; i >= 0; i--)
							{
								if (dt[i].leaf)
								{
									dt.splice(i, 1);
								}
							}
							
							me.gridupdate.execute(node);
						}
						
						var dt_now = new Date();

						dt.length && node.appendChild(dt);

						void 0;
						
						if (me._expandedNodes && node.childNodes)
						{
							$.each(node.childNodes, function(i, lnode) {
								var luid = lnode.get("uid");
								if (me._expandedNodes[luid])
								{
									lnode.expand();
									delete me._expandedNodes[luid];
								}
							});
						}
						
						if (me.ntrnode == node)
						{
							me.navigateTreeOpen();
						}
						else if (me.ntrnode)
						{
							me.ntrnode = null;
						}
						
						if (me.custom_expanded_func)
						{
							me.custom_expanded_func.execute(node);
						}
						
						if (me.store && me.store.__cb)
						{
							me.store.__cb.execute();
						}
					};
					
					if (me.request_override)
					{
						me.request_override.execute({
							ack: "content", 
							payload: addr, 
							mbody: {subfolder:"T"}
						}, new IG$.callBackObj(me, req_handler));
					}
					else
					{
						me.__loaded && me.setLoading(true);
						
						req.init(me, 
							{
								ack: "content",
								payload: addr,
								mbody: {subfolder: "T"}
							}, me, req_handler
						);
						req.send();
					}
				}
			}
		});
		
		IG$.n$navTreeCom.superclass.initComponent.call(this);
	}
});


