

/**
 * fieldset control
 */
IG$._FC_fieldset = $s.extend(IG$._baseFC, {
	objtype: "fieldset",
	iscontainer: true,
	create: function(container) {
		var me = this,
			fmodel = me.fmodel,
			fitem = me.fitem,
			mcap = me.mcap,
			stext = fmodel.title || " ",
			ui;
			
		
		ui = $("<fieldset><legend></legend></fieldset>")
			.appendTo(container);
		
		if (stext)
		{
			$("legend", ui).html(stext);
		}
		
		return ui;
	},
	text: function(value) {
		var me = this,
			ui = ui;
			
		$("legend", ui).html(value);
	},
	$setProp: function(fitem, key, value) {
		var me = this;
		if (key == "title")
		{
			me.text(value);
		}
		IG$._baseFC.prototype.$setProp.call(me, fitem, key, value);
	}
});

IG$.$FCinst["fieldset"] = new IG$._FC_fieldset();