IG$.naviTree = $s.extend($s.panel, {
	
	setRootNode: function(values) {
		var me = this,
			sinp = me.down("[name=sinp]"),
			rnode;
		
		sinp.setValue("");
		me.m_c.getLayout().setActiveItem(0);
		rnode = me.m_0.setRootNode(values);
		
		return rnode;
	},
	
	getRootNode: function() {
		return this.m_0.getRootNode();
	},
	
	doSearch: function() {
		var me = this,
			sinp = me.down("[name=sinp]"),
			skey = sinp.getValue(),
			m_1 = me.m_1,
			req,
			tuid,
			rnode = me.m_0.getRootNode();
		
		if (skey)
		{
			sinp.clearInvalid();
			m_1.store.loadData([]);
			me.m_c.getLayout().setActiveItem(1);
			
			tuid = rnode.get("uid");
			
			req = new IG$._rpc$();
			req.init(me, 
				{
					ack: "helpcontent",
					payload: {uid: tuid},
					mbody: {option: "search", name: skey, pid: tuid, metatypes: me.metatypes || "Table;Metric;CustomMetric;Measure;MeasureFormula;Report;Datemetric;Folder"}
				}, me, function(jdoc) {
					var tnodes = (jdoc && jdoc.children && jdoc.children.length ? jdoc.children : null),
						i, dp = [], p;
						
					if (tnodes)
					{
						for (i=0; i < tnodes.length; i++)
						{
							p = tnodes[i];
							p.ltype = p.type.toLowerCase();
							p.iconcls = IG$.get_metatype_icon(p.ltype, p);
							dp.push(p);
						}
					}
					
					m_1.store.loadData(dp);
				}, null);
			req.send();
		}
		else
		{
			sinp.markInvalid("Required!");
			me.m_c.getLayout().setActiveItem(0);
		}
	},
	
	refreshTree: function() {
		var me = this,
			m_0 = me.down("[name=m_0]");
		
		m_0.refreshTree();
	},
	
	getSelectionModel: function() {
		var me = this,
			m_0 = me.down("[name=m_0]");
		
		return m_0.getSelectionModel();
	},
	
	setFilter: function(fitem) {
		var me = this,
			m_0 = me.down("[name=m_0]");
		me._fitem = fitem;
		
		m_0.setFilter(fitem);
	},
	
	$getTreeData: function() {
		var me = this,
			m_0 = me.down("[name=m_0]"),
			rootnode = m_0.getRootNode(),
			rdata = {};
		
		rdata = me._updateRootTree(rootnode, null);
		
		return rdata;
	},
	
	_updateRootTree: function(rnode, pnode) {
		var r,
			me = this,
			cdata = rnode.data,
			i,
			sr;
		
		r = {
			name: cdata.name,
			nodepath: cdata.nodepath,
			type: cdata.type,
			uid: cdata.uid,
			writable: cdata.writable,
			leaf: cdata.leaf,
			address: cdata.address,
			description: cdata.description,
			attributes: cdata.attributes,
			icon: cdata.icon,
			iconCls: cdata.iconCls,
			is_sub: cdata.is_sub,
			lfd: cdata.lfd,
			locale_name: cdata.local_name,
			ltype: cdata.ltype,
			manage: cdata.manage,
			memo: cdata.memo,
			mid: cdata.mid,
			modifier: cdata.modifier,
			objinfo: cdata.objinfo,
			owner: cdata.owner,
			pid: cdata.pid,
			revision: cdata.revision,
			sid: cdata.sid,
			text: cdata.text,
			updatedate: cdata.updatedate,
			updatedatefm: cdata.updatedatefm,
			datatype: cdata.datatype
		};
		
		if (rnode.childNodes && rnode.isExpanded())
		{
			r.children = [];
			for (i=0; i < rnode.childNodes.length; i++)
			{
				sr = me._updateRootTree(rnode.childNodes[i]);
				r.children.push(sr);
			}
		}
		
		return r;
	},
	
	initComponent: function() {
		var me = this,
			i, t;
		
		$s.apply(this, {
			border: 0,
			layout: {
				type: "vbox",
				align: "stretch"
			},
			items: [
				{
					xtype: "container",
					layout: {
						type: "hbox",
						pack: "center"
					},
					height: 30,
					hidden: me._search != true || me.meta_type == "sql_report",
					items: [
						{
							xtype: "container",
							name: "m_search",
							layout: {
								type: "hbox",
								align: "stretch"
							},
							flex: 1,
							items: [
								{
									xtype: "textfield",
									name: "sinp",
									flex: 1,
									placeholder: IRm$.r1("L_SEARCH_KWD"),
									enableKeyEvents: true,
									listeners: {
										keyup: function(comp, e) {
											var me = this,
												sinp = me.down("[name=sinp]"),
												sclose = me.down("[name=sclose]");
												
											if (e.keyCode == 13)
											{
												sinp.getValue() && sclose.show();
												me.doSearch();
											}
										},
										scope: this
									}
								},
								{
									xtype: "button",
									iconCls: "icon-toolbar-search",
									tooltip: IRm$.r1("B_SEARCH"),
									handler: function() {
										var me = this,
											sinp = me.down("[name=sinp]"),
											sclose = me.down("[name=sclose]");
											
										sinp.getValue() && sclose.show();
										
										me.doSearch();
									},
									scope: this
								},
								{
									xtype: "button",
									text: "X",
									name: "sclose",
									hidden: true,
									handler: function() {
										var me = this,
											sinp = me.down("[name=sinp]"),
											sclose = me.down("[name=sclose]");
											
										sinp.setValue("");
										me.m_c.getLayout().setActiveItem(0);
										sclose.hide();
									},
									scope: this
								}
							]
						},
						{
							xtype: "button",
							type: "refresh",
							margin: "4 2 0",
							iconCls: "icon-refresh",
							tooltip: IRm$.r1("B_REFRESH"),
							handler: function(event, toolEl, panelHeader) {
								var me = this;
								
								me.refreshTree();
							},
							scope: this
						}
					]
				},
				{
					xtype: "panel",
					flex: 1,
					layout: "card",
					name: "m_c",
					defaults: {
						deferredRender: false
					},
					items: [
						new IG$.n$navTreeCom({
							instance: me.instance,
							name: "m_0",
							border: 0,
							rootuid: me.rootuid,
							initpath: me.initpath,
							mainPanel: me.mainPanel,
							showtoolbar: me.showtoolbar,
							showcheckselect: me.showcheckselect,
							
							ddGroup: me.ddGroup,
							enabledrag: me.enabledrag,
							
							meta_type: me.meta_type,
							rptptr: me.rptptr,
							
							nav_options: me.nav_options,
							request_override: me.request_override,
							custom_click_func: me.custom_click_func,
							custom_expand_func: me.custom_expand_func,
							custom_expanded_func: me.custom_expanded_func,
							custDblClickFunc: me.custDblClickFunc,
							checkStateChanged: me.checkStateChanged,
							visibleItems: me.visibleItems,
							hiddenItems: me.hiddenItems,
							isdatasource: me.isdatasource,
							tree_options: me.tree_options
						}),
						{
							xtype: "gridpanel",
							name: "m_1",
							emptyText: IRm$.r1("L_EMPTY"),
							viewConfig: {
								plugins: {
									ptype: "gridviewdragdrop",
									ddGroup: me.ddGroup,
									enabledrag: me.enabledrag
								}
							},
							store: {
								fields: [
									"uid", "name", "type", "nodepath", "iconcls", "lname"
								]
							},
							selModel: {
								mode: "MULTI"
							},
							columns: [
								{
									width: 25,
									renderer: function(value, metadata, record) {
										return "<div class='ig-navi-itemicon " + (record.get("iconcls") || "") + "'></div>";
									}
								},
								{
									// xtype: "templatecolumn",
									text: IRm$.r1("B_NAME"),
									flex: 1,
									tdCls: "ig-navi-namecol",
									// tpl: "<div class='ig-navi-itemicon {iconcls}'></div><span title='{nodepath}'>{name}</span>"
									renderer: function(value, metadata, record) {
										var tt = record.get("locale_name") || record.get("name");
										if (record.get("locale_name"))
										{
											tt += "(" + record.get("locale_name") + ")";
										}
										tt += "\n==>" + (record.get("nodepath") || "");
										// class='ig-navi-itemicon " + (record.get("iconcls") || "") + "' 
										return "<span title='" + IG$.hEE(tt) + "'>" + IG$.hEE(record.get("locale_name") || record.get("name")) + "</span>";
									}
								},
								{
									xtype: "actioncolumn",
									width: 30,
									items: [
										{
											iconCls: "icon-grid-dbicon",
											handler: function (grid, rowIndex, colIndex) {
												var me = this,
													record = grid.store.data.items[rowIndex];
													itemtype = record.get("type").toLowerCase();
													
												me.m_c.getLayout().setActiveItem(0);
												me.m_0.navigateTree({
													uid: record.get("uid"),
													nodepath: record.get("nodepath"),
													type: record.get("type")
												});
											},
											scope: this
										}
									]
								}
							],
							listeners: {
								cellclick: function(tobj, node, c, record, index, e) {
									var me = this,
										bproc,
										data = record.data;
										
									if (me.custom_click_func)
									{
										bproc = me.custom_click_func.execute(record, data);
									}
								},
								itemdblclick: function(tobj, record, item, index, e, eopts) {
									var me = this;
									
									if (me.custDblClickFunc)
									{
										bproc = me.custDblClickFunc.execute(record);
									}
								},
								scope: this
							}
						}
					]
				}
			]
		});
		
		if (me.tools && me.tools.length)
		{
			for (i=0; i < me.tools.length; i++)
			{
				me.items[0].items.push(me.tools[i]);
			}
		}
		
		me.on("afterrender", function(tobj) {
			var me = tobj,
				m_search = me.down("[name=m_search]"),
				sbox, sbtn,
				sinp,
				sclose;
				
			me.m_0 = me.down("[name=m_0]");
			me.m_1 = me.down("[name=m_1]");
			me.m_c = me.down("[name=m_c]");
			
			me.m_0.on("refreshTree", function(view, record) {
				me.refreshTree();
				return 1;
			});
		});
		
		IG$.naviTree.superclass.initComponent.call(this);
	}
});