/***********************************************************************
 * AppPageControl: TabPanel 
 */
 IG$.ctrlTabPanel = IG$.extend(IG$.ctrlBase, {
	type: "tabpanel",
	iscontainer: true,
	initComponent: function() {
		var me = this;
		me.activeIndex = 0;
		me.p.push(
			{name: "flexHeight", type: "property", datatype: "number", value: 0},
			{name: "minHeight", type: "property", datatype: "number", value: 0}
		);
		
		me.superclass.prototype.initComponent.call(me);
	},
	
	processEvent: function(evttype, obj) {
	},

	invalidate: function () {
		var me = this;
	},
	
	initDrawing: function () {
		var me = this,
			w = IG$.j$ext._w(me.html),
			h = IG$.j$ext._h(me.html),
			actionlist = me.ctrl.actionlist,
			renderto = me.el$,
			tabbuttons = $("<ul class='ig-db-tab-btnarea'></ul>").appendTo(renderto),
			mainarea = $("<div class='ig-db-tabarea'></div>").appendTo(renderto);
		
		me.tl$.hide();
		me.tabbuttons = tabbuttons;
		me.mainarea = mainarea;
		
		me.__pcinit();
	},
	updateProperty: function(kname, value) {
		var me = this;
		
		if (me.dsmode)
		{
			return;
		}
		
		switch(kname)
		{
		case "report_control":
			break;
		}
	},

	updateLayout: function() {
		var me = this,
			dashboard = me.ctrl.dashboard;
	},

	loadHeader: function(items) {
		var me = this,
			tabbuttons = me.tabbuttons,
			i;

		me.tabitems = items;
		tabbuttons.empty();

		$.each(items, function(i, item) {
			var li = $("<li><span>" + (item.title || "Tab " + (i+1)) + "</li>").appendTo(tabbuttons);

			if (me.activeIndex == i)
			{
				li.addClass("active");
			}

			item.__tab_btn = li;

			li.bind("click", function() {
				me.setActiveItem(i);
			})
		});
	},
	
	getTabHeight: function() {
		return this.tabbuttons ? this.tabbuttons.height() : 0;
	},

	setActiveItem: function(index) {
		var me = this,
			i;

		if (me.tabitems && me.tabitems.length > index && index > -1)
		{
			me.activeIndex = index;
		}

		if (me.activeIndex > -1 && me.tabitems)
		{
			for (i=0; i < me.tabitems.length; i++)
			{
				if (index == i)
				{
					me.tabitems[i].__tab_btn.addClass("active");
				}
				else
				{
					me.tabitems[i].__tab_btn.removeClass("active");
				}

				me.tabitems[i].controls.html[index == i ? "show" : "hide"]();
			}
		}
	}
});

IG$.controls.tabpanel = new IG$.ctrlTabPanel({}, null);