/**
 * calendarperiod control
 */
IG$._FC_calendarperiod = $s.extend(IG$._baseFC, {
	objtype: "calendarperiod",
	s_codemap: 1,
	s_metric: 1,
	events: [
		{name: "change_val"}
	],
	create: function(container) {
		var me = this,
			fitem = me.fitem,
			fmodel = me.fmodel,
			ui = $("<div class='mec-dateperiod-box'></div>")
				.appendTo(container),
			dsel1 = $("<div class='period1'></div>"),
			dsel2 = $("<div class='period2'></div>"),
			dateseltype = fmodel.dateseltype,
			select_tag = me.md ? "md-outlined-select" : "select",
			option_tag = me.md ? "md-select-option" : "option",
			dselector,
			dselector_menu,
			ismonth = false,
			isyear = false,
			ys = fmodel.yearfrom || "cyear-5", 
			ye = fmodel.yearto || "cyear",
			dt1, dt2, mp1, mp2,
			rangelabel = me.rangelabel,
			_init_value = fmodel._init_value || fmodel.initial_values,
			calendar_locale = IG$.calendar_locale,
			_init_from,
			_init_to;

		dselector = me.md ? $("<md-icon-button><md-icon>more_vert</md-icon></md-icon-button>").appendTo(ui) : $("<" + select_tag + " class='mec-dateperid-sel'></" + select_tag + ">").appendTo(ui);

		if (me.md)
		{
			dselector_menu = $("<md-menu class='mec-dateperid-sel' positioning='popover'></md-menu>").appendTo(ui);
			dselector_menu[0].anchorElement = dselector[0];
		}

		dsel1.appendTo(ui);
		dsel2.appendTo(ui);
		
		dselector[fmodel.showperiodselector ? "show" : "hide"]();

		dselector[0].addEventListener("click", function() {
			dselector_menu[0].open = !dselector_menu[0].open;
		});

		if (_init_value && _init_value.length)
		{
			var t1 = me.getDefaultValue(fitem, 0),
				t2 = me.getDefaultValue(fitem, 1);

			if (t1)
			{
				_init_from = me.getDefaultDate(t1);
			}

			if (t2)
			{
				_init_to = me.getDefaultDate(t2);
			}
		}
		
		ys = me.getYearField(ys);
		ye = me.getYearField(ye);
		
		var _cal_year = function(dsel, seq) {
			var fid = me._get_id(),
				mp;
			if (me.md)
			{
				me["lbl" + (seq == 1 ? "" : seq) + "$"] = $("<label class='form-label' for='" + fid + "'></label>");
			}
			
			var dt = $("<" + select_tag + "></" + select_tag + ">").appendTo(dsel);

			if (me.md)
			{
				me["mp" + (seq == 1 ? "" : seq) + "$"] = dt[0];
			}
			
			me._pop_dtval(fitem, dt, dateseltype, seq, seq == 1 ? fmodel.startdate : fmodel.enddate);
			
			dt.bind("change", function() {
				seq == 1 && me._ud_dt2s(fitem, dateseltype);
				me.trigger("change_val");
			});
							
			return {dt: dt, mp: mp};
		}
		
		var _cal_month = function(dcon, seq) {
			var ptn = "yyyy-mm",
				fid = me._get_id(),
				dsel = $("<div class='am-pcontainer'></div>").appendTo(dcon),
				dt, mp;

			if (me.md)
			{
				dsel.addClass("form-outline");
				lbl$ = me["lbl" + (seq == 1 ? "" : seq) + "$"] = $("<label class='form-label' for='" + fid + "'></label>"); // .appendTo(dsel);
				// $("<div class='form-helper'></div>").appendTo(dsel);

				mp = me["mp" + (seq == 1 ? "" : seq) + "$"] = $("<md-outlined-text-field class='igc-md-ctrl' style='flex:1;' placeholder='" + calendar_locale.c2disp + "'></md-outlined-text-field>").appendTo(dsel)[0];
				mp.update();

				dt = $("<input type='text'></input>")
					.css({
						position: "absolute",
						top: 0,
						bottom: 0,
						left: 0,
						width: 0,
						border: 0
					})
					.appendTo(ui);

				mp.addEventListener("change", function(e) {
					if (dt.val() != mp.value)
						dt.val(mp.value);
				});
			}
			else
			{
				dt = $("<input class='mec-dateperiod-input' type='text' placeholder='" + calendar_locale.c2disp + "' id='" + fid + "'></input>").appendTo(dsel);
			}

			dt.monthpicker({
				monthNames: $.datepicker._defaults.monthNamesShort,
				constrainInput: false,
				buttonImageOnly: true,
				pattern: ptn,
				startYear: ys,
				finalYear: ye,
				dateFormat: calendar_locale.c2format
			});
			
			seq == 1 && dt.bind("change", function(e) {
				me._ud_dt2s(fitem, dateseltype);
				me.trigger("change_val");
			});
			
			seq == 2 && IG$.dateUtil.updateDatePicker(dt);
			
			me._pop_dtval(fitem, dt, dateseltype, seq, seq == 2 && fmodel.enddate ? me.getDefaultDate(fmodel.enddate) : null);
			
			$("<div class='mec-dateperiod-button" + (me.md ? " idv-float-button" : "") + "'>&nbsp;</div>").appendTo(dsel).bind("click", function() {
				dt.monthpicker("show");
				me.md && me._sync_val(mp, dt, seq);
			});
			
			return {dt: dt, mp: mp};
		}
		
		var _cal_date = function(dcon, seq) {
			var fid = me._get_id(),
				ptn = "yyyy-mm-dd",
				dt, mp
				dsel = $("<div class='am-pcontainer'></div>").appendTo(dcon);

			if (me.md)
			{
				dsel.addClass("form-outline");

				lbl$ = me["lbl" + (seq == 1 ? "" : seq) + "$"] = $("<label class='form-label' for='" + fid + "'></label>"); // .appendTo(dsel);
				// $("<div class='form-helper'></div>").appendTo(dsel);

				mp = me["mp" + (seq == 1 ? "" : seq) + "$"] = $("<md-outlined-text-field class='igc-md-ctrl' style='flex:1' placeholder='" + ptn + "'></md-outlined-text-field>").appendTo(dsel)[0];
				mp.update();
				dt = $("<input type='text'></input>")
					.css({
						position: "absolute",
						top: 0,
						bottom: 0,
						left: 0,
						width: 0,
						border: 0
					})
					.appendTo(ui);

				mp.addEventListener("change", function(e) {
					if (dt.val() != mp.value)
						dt.val(mp.value);
				});
			}
			else
			{
				dt = $("<input class='mec-dateperiod-input' type='text' placeholder='" + ptn + "' id='" + (fid) + "'></input>").appendTo(dsel);
				dt.css({zIndex: 100});
			}
			
			dt.startYear = ys;
			dt.finalYear = ye;
			
			IG$.dateUtil.createDatePicker(me, dt, function(dateText, inst) {
				var dt1 = fitem.dt1,
					dt2 = fitem.dt2;
				me._ud_dt2s(fitem, dateseltype);
				if (seq == 1 && dt1.datepicker("getDate") && dt2 && dt2.datepicker("getDate"))
				{
					me.trigger("change_val");
				}
				else if (seq == 2 && dt1.datepicker("getDate") && dt2.datepicker("getDate"))
				{
					me.trigger("change_val");
				}
			}, mp);
			
			me._pop_dtval(fitem, dt, dateseltype, seq);
			
			$("<div class='mec-dateperiod-button" + (me.md ? " idv-float-button" : "") + "'>&nbsp;</div>").appendTo(dsel).bind("click", function() {
				dt.datepicker("show");
				me.md && me._sync_val(mp, dt, seq);
			});
							
			return {dt: dt, mp: mp};
		}
		
		var _plabel = function(dsel, pos) {
			var Lt = me.getRangeLabel(rangelabel, 
					pos == 1 || pos == 2 ? 0 : 2, 
					pos == 1 || pos == 3 ? 0 : 1, 
					2),
				S;
			if (Lt)
			{
				S = $("<div class='igc-f-range-label-td'></div>").appendTo(dsel);
				$(Lt.d).appendTo(S);
			}
		}
					
		if (dateseltype == "year")
		{
			isyear = true;
			ismonth = false;
			
			_plabel(dsel1, 1);
			var cobj = _cal_year(dsel1, 1);
			dt1 = fitem.dt1 = cobj.dt;
			_plabel(dsel1, 2);
		}
		else if (dateseltype == "month")
		{
			ismonth = true;
			isyear = false;
			
			_plabel(dsel1, 1);
			var cobj = _cal_month(dsel1, 1);
			dt1 = fitem.dt1 = cobj.dt;
			mp1 = fitem.mp1 = cobj.mp;
			_plabel(dsel1, 2);
		}
		else
		{
			_plabel(dsel1, 1);
			var cobj = _cal_date(dsel1, 1);
			dt1 = fitem.dt1 = cobj.dt;
			mp1 = fitem.mp1 = cobj.mp;
			_plabel(dsel1, 2);
		}
		
		let Lt = (me.getRangeLabel(rangelabel, 1, 0, 2));
		if (Lt)
		{
			S = $("<div class='igc-f-range-label-td'></div>").appendTo(dsel1);
			$(Lt.d).appendTo(S);
		}

		if (dateseltype == "year")
		{
			isyear = true;
			ismonth = false;
			
			_plabel(dsel2, 3);
			var cobj = _cal_year(dsel2, 2);
			dt2 = fitem.dt2 = cobj.dt;
			mp2 = fitem.mp2 = cobj.mp;
			_plabel(dsel2, 4);
		}
		else if (dateseltype == "month")
		{
			ismonth = true;
			isyear = false;
			
			ptn = "yyyy-mm";
			
			_plabel(dsel2, 3);
			var cobj = _cal_month(dsel2, 2);
			dt2 = fitem.dt2 = cobj.dt;
			mp2 = fitem.mp2 = cobj.mp;
			_plabel(dsel2, 4);
		}
		else
		{
			_plabel(dsel2, 3);
			var cobj = _cal_date(dsel2, 2);
			dt2 = fitem.dt2 = cobj.dt;
			mp2 = fitem.mp2 = cobj.mp;
			_plabel(dsel2, 4);
		}	
		
		var default_period;
		
		if (!fmodel.startdate && !fmodel.enddate && fmodel.showperiodselector && fmodel.periodlist)
		{
			$.each(fmodel.periodlist, function(i, prd_i) {
				if (me.md)
				{
					var menu_item = $("<md-menu-item" + (prd_i.isdefault ? " selected" : "") + ">" + prd_i.name + "</md-menu-item>").appendTo(dselector_menu);

					menu_item[0].addEventListener("click", function() {
						dselector[0].value = prd_i.value;

						dselector_handler();
					});
				}
				else
				{
					$("<" + option_tag + " value='" + prd_i.value + "'" + (prd_i.isdefault ? " selected" : "") + ">" + prd_i.name + "</" + option_tag + ">").appendTo(dselector);
				}
				
				if (prd_i.isdefault)
				{
					default_period = [
						IG$.dynFilterDateConfig.getValue(prd_i.value, 0, ismonth, isyear), 
						null
					];

					if (default_period[0])
					{
						default_period[1] = new Date();
					}
				}
			});
		}
		else if (_init_from || _init_to)
		{
			default_period = [_init_from, _init_to];
		}
			
		if (default_period)
		{
			$.each([dt1, dt2], function(k, dt) {
				var t = default_period[k] && typeof(default_period[k]) == "object" && default_period[k].getMonth ? 1 : 0;
				if (isyear)
				{
					var syear = t ? "" + default_period[k].getFullYear() : default_period[k];

					if (me.md)
					{
						if (k == 0)
						{
							me.mp$.value = syear;
						}
						else
						{
							me.mp2$.value = syear;
						}
					}
					else
					{
						var sopt = $("option", dt),
							sik, ik;
							
						for (ik=0; ik < sopt.length; ik++)
						{
							sik = $(sopt[ik]);
							if (sik.val() == syear)
							{
								sik.attr("selected", "selected");
							}
						}
					}
					
					k == 1 && me._ud_dt2s(fitem, dateseltype);
				}
				else if (ismonth)
				{
					var r1 = default_period[k];
					
					if (r1)
					{
						if (t)
						{
							dt.monthpicker("setDate", r1);
						}
						else
						{
							r1 = r1.split("-").join("") + "01";
							dt.monthpicker("setDate", me.getDefaultDate(r1));
						}
						me.md && me._sync_val(k == 0 ? me.mp$ : me.mp2$, dt);
						k == 0 && me._ud_dt2s(fitem, dateseltype);
					}
				}
				else
				{
					var r1 = default_period[k];
					
					if (r1)
					{
						if (t)
						{
							dt.datepicker("setDate", r1);	
						}
						else
						{
							r1 = r1.split("-").join("");
							dt.datepicker("setDate", me.getDefaultDate(r1));
						}
						me.md && me._sync_val(k == 0 ? me.mp$ : me.mp2$, dt, k);
						k == 0 && me._ud_dt2s(fitem, dateseltype);
					}
				}
				
				if (k == 1)
				{
					setTimeout(function() {
						dselector.trigger("change");
					}, 100);
				}
			});
		}

		function dselector_handler() {
			var sel = me.md ? dselector[0].value : $("option:selected", dselector).val();
			if (sel)
			{
				$.each([0, 1], function(k, v) {
					var dt = k == 0 ? dt1 : dt2;
					if (isyear)
					{
						var syear = IG$.dynFilterDateConfig.getValue(sel, k, ismonth, isyear);

						if (me.md)
						{
							if (k == 0)
							{
								me.mp$.value = syear;
							}
							else
							{
								me.mp2$.value = syear;
							}

							if (k == 1 && me.mp$.value && me.mp2$.value)
							{
								me.trigger("change_val");
							}
						}
						else
						{
							var sopt = $("option", dt),
								ik, sik;
								
							for (ik=0; ik < sopt.length; ik++)
							{
								sik = $(sopt[ik]);
								if (sik.val() == syear)
								{
									sik.attr("selected", "selected");
								}
							}
							
							if (k == 1 && $("option:selected", dt1).val() && $("option:selected", dt2).val())
							{
								me.trigger("change_val");
							}
						}
					}
					else
					{
						var s1 = IG$.dynFilterDateConfig.getValue(sel, k);
						dt[ismonth ? "monthpicker" : "datepicker"]("setDate", IG$.dynFilterDateConfig.transDate(s1));
						
						if (me.md)
						{
							if (k == 0)
							{
								me.mp$.value = dt1.val();
							}
							else
							{
								me.mp2$.value = dt2.val();
							}

							if (k == 1 && dt1.val() && dt2.val())
							{
								me.trigger("change_val");
							}
						}
						else
						{
							if (k == 1 && dt1.val() && dt2.val())
							{
								me.trigger("change_val");
							}
						}
					}
				});
			}
		}
		
		if (fmodel.showperiodselector)
		{
			if (me.md)
			{
				// dselector[0].addEventListener("change", dselector_handler);
			}
			else
			{
				dselector.bind("change", dselector_handler);
			}
		}
		
		return ui;
	},
	setValue: function(values, cmap, svalues) {
		var me = this,
			fitem = me.fitem,
			dateseltype = me.fmodel.dateseltype;
			
		if (dateseltype == "year")
		{
			fitem.dt1.val(values[0]);
			fitem.dt2.val(values[1]);
		}
		else if (dateseltype == "month")
		{
			fitem.dt1.monthpicker("setDate", me.getDefaultDate(values[0]));
			fitem.dt2.monthpicker("setDate", me.getDefaultDate(values[1]));
		}
		else
		{
			fitem.dt1.datepicker("setDate", me.getDefaultDate(values[0]));
			fitem.dt2.datepicker("setDate", me.getDefaultDate(values[1]));
		}
	},
	updateValue: function(value) {
		var me = this,
			fitem = me.fitem,
			dateseltype = me.fmodel.dateseltype;
			
		if (dateseltype == "year")
		{
			value1 = $("option:selected", fitem.dt1).val();
			value2 = $("option:selected", fitem.dt2).val();
		}
		else if (dateseltype == "month")
		{
			value1 = fitem.dt1.monthpicker("getDate");
			value2 = fitem.dt2.monthpicker("getDate");
			if (value2)
			{
				value2 = new Date(value2.getFullYear(), value2.getMonth()+1, 0);
			}
		}
		else
		{
			value1 = fitem.dt1.datepicker("getDate");
			value2 = fitem.dt2.datepicker("getDate");
		}
		
		if (value1 && value2)
		{
			if (dateseltype == "year")
			{
				value1 = value1 + "0101000000";
				value2 = value2 + "1231235959";
			}
			else
			{
				value1 = value1.format("Ymd") + "000000";
				value2 = value2.format("Ymd") + "235959";
			}
			
			if (Number(value1) < Number(value2))
			{
				value.push({code: value1, value: value1, operator: "GTE", valuetype: "date"});
				value.push({code: value2, value: value2, operator: "LTE", valuetype: "date"});
			}
			else
			{
				r = 0;
			}
		}
	},
	clear: function() {
		var me = this,
			fitem = me.fitem,
			dateseltype = me.fmodel.dateseltype;
			
		if (dateseltype == "year")
		{
			fitem.dt1.val("");
			fitem.dt2.val("");
		}
		else if (dateseltype == "month")
		{
			fitem.dt1.monthpicker("setDate", null);
			fitem.dt2.monthpicker("setDate", null);
		}
		else
		{
			fitem.dt1.datepicker("setDate", null);
			fitem.dt2.datepicker("setDate", null);
		}
	}
});

IG$.$FCinst["calendarperiod"] = new IG$._FC_calendarperiod();