var clsscript = {},
	fnglobal = {},
	__jsmod = {};
	
/**
  dynamic filter information
  
  type: 
  	filter_validate: filter item selected value validation
  	filter_exec: filter button before handler
  	report_load: report data loaded handler
  	report_click: report cell click handler
  	report_dblclick: report cell double click handler
  	
  script_01: {
  	name: "script to test",
  	type: "specify type",
  	handler: function() {
  	}
  }
*/

IG$.cDynScript = function(uid, base_class) {
	this.uid = uid;
	this.base_class = base_class;
	this.lastError = null;
}

IG$.cDynScript.prototype = {
	loadScript: function(js) {
		var me = this,
			doc = document,
			head = $('head'),
			jsmode,
			browser = window.bowser;
			
		jsmode = __jsmod[me.uid];
		
		if (!jsmode)
		{
			jsmode = document.createElement('script'); // '<script id="clsscript" type="text/javascript"></script>');
			jsmode.id = 'clsscript';
			jsmode.type = 'text/javascript';
			
			head[0].appendChild(jsmode);
			
			__jsmod[me.uid] = jsmode;
		}
		
		delete clsscript[me.uid];
		
		var jscontent;
		
		if (me.base_class === 0)
		{
			jscontent = js;
		}
		else if (me.base_class)
		{
			jscontent = "clsscript['" + me.uid + "'] = IG$.extend(" + me.base_class + ", {\n" + js + "\n});" 
		}
		else
		{
			jscontent = "function " + this.uid + "() {}; " + this.uid + ".prototype={" + js + "}; clsscript['" + this.uid + "'] = " + this.uid + ";";
		}
		
		if (browser.msie)
		{
			jsmode.text = jscontent;
		}
		else
		{
			jsmode.innerHTML = jscontent;
		}
		
		delete fnglobal[me.uid];
		
		head[0].removeChild(jsmode);
		delete __jsmod[me.uid];
		
		if (me.base_class !== 0)
		{
			var nfunc = {};
			
			try
			{
				var fn = clsscript[me.uid];
				nfunc = new fn();
			}
			catch (e)
			{
				void 0;
				IG$.ShowError(IRm$.r1("E_SC_LD"), null, null, {errstack: e.stack});
			}
					
			fnglobal[this.uid] = nfunc;
		}
	},
	
	preparePrototype: function(controls, main) {
		var fn = fnglobal[this.uid];
		
		if (fn)
		{
			fn.controls = controls;
			fn.ptr_main = main;
			fn.parameters = main.framecontent.page_param_map;
		}
	},
	
	executeScript: function(scname) {
		var cdynscript = fnglobal[this.uid],
			args = arguments,
			r = true;
		
		args = Array.prototype.slice.call(args, 1);
		this.lastError = null;
		
		try
		{
			if (!cdynscript[scname])
			{
				this.lastError = "Function call: " + scname + " not found";
				return false;
			}
			r = cdynscript[scname].apply(cdynscript, args);
		}
		catch (e)
		{
			void 0;
			this.lastError = "Error: " + scname + "\n"
						   + this.printStackTrace().join('\n\n');
			return false;
		}
		
		return r;
	},
	
	getFunctionList: function() {
		var cdynscript = fnglobal[this.uid],
			r = [],
			key,
			obj,
			objtype;
		
		if (cdynscript)
		{
			for (key in cdynscript)
			{
				obj = cdynscript[key];
				objtype = typeof(obj);
				
				if (objtype == "function" && key.charAt(0) != '$' && key != "override")
				{
					r.push(key);
				}
			}
		}
		
		return r;
	},
	
	printStackTrace: function() {
		  var callstack = [],
			  isCallstackPopulated = false;
		  
		  try {
			i.dont.exist+=0; //doesn't exist- that's the point
		  } catch(e) {
		  	void 0;
			if (e.stack) { //Firefox
				  var lines = e.stack.split('\n');
				  for (var i=0, len=lines.length; i<len; i++) {
					if (lines[i].match(/^\s*[A-Za-z0-9\-_\$]+\(/)) {
						  callstack.push(lines[i]);
					}
				  }
				  //Remove call to printStackTrace()
				  callstack.shift();
				  isCallstackPopulated = true;
			}
			else if (window.opera && e.message) { //Opera
				  var lines = e.message.split('\n');
				  for (var i=0, len=lines.length; i<len; i++) {
					if (lines[i].match(/^\s*[A-Za-z0-9\-_\$]+\(/)) {
						  var entry = lines[i];
						  //Append next line also since it has the file info
						  if (lines[i+1]) {
							entry += ' at ' + lines[i+1];
							i++;
						  }
						  callstack.push(entry);
					}
				  }
				  //Remove call to printStackTrace()
				  callstack.shift();
				  isCallstackPopulated = true;
			}
		  }
		  if (!isCallstackPopulated) { //IE and Safari
			var currentFunction = arguments.callee.caller;
			while (currentFunction) {
				  var fn = currentFunction.toString();
				  var fname = fn.substring(fn.indexOf("function") + 8, fn.indexOf('')) || 'anonymous';
				  callstack.push(fname);
				  currentFunction = currentFunction.caller;
			}
		  }
		  // output(callstack);
		  return callstack;
	}
}