/**
 * @module widget/rfReportViewer
 * @desc Report Viewer Control
 *
 */
IG$.rfReportViewer = function (instance, container, sop, owner) {
	var me = this;
	
	me.instance = instance;
	me.container = container;
	me.sheetoption = sop;
	me.owner = owner;
	
//	if (me.owner && me.owner.box)
//	{
//		me.owner.box.bind("updatecomplete", function() {
//			me.validateItems();
//		});
//	}
	
	me.updateValues = true;
	me.active = null;
	me.validated = false;
	me.validateFilter = true;
	me.f_run = true;
	
	me.$init();
};

IG$.rfReportViewer.prototype = {
	$init: function() {
		var me = this;
		me.contentarea = $("<div class='igc-rpt-view'></div>").appendTo(me.container);
		
		// me.validateItems();
	},
	
	/**
	 * validate and execute report inside with timer 50 milisecond 
	 */
	executeItem: function() {
		var me = this;
		
		if (me.validateFilter || me.f_run)
		{
			me.f_run = false;
			
			clearTimeout(me._validateCall);
			
			me._validateCall = setTimeout(function() {
				me.executeValidate();
			}, 50);
		}
	},
	
	/**
	 * execute report immediately. Called from executeItem with timer
	 */
	executeValidate: function() {
		var me = this,
			i,
			sheet, sop;
		
		if (!me.irpt)
		{
			me.validateItems();
		}
		else
		{
			var run_sheets = [];
			
			for (i=0; i < me.irpt.sheets.length; i++)
			{
				sheet = me.irpt.sheets[i];
				sop = sheet.sheetoption;
				
				var preq;
				
				if (me._directFilter)
				{
					auxfilter = sop.model.aux_filter;
					for (fname in me._directFilter)
					{
						auxfilter[fname] = me._directFilter[fname];
					}
				}
				
				if (sheet.olapset)
				{
					pivotxml = sheet.olapset.reportoption.getCurrentPivot();
					preq = sheet.olapset.requestUpdateReport(pivotxml, "mode", i, sheet);
				}
				else if (sop)
				{
					preq = sheet.procRunReport();
				}
				
				if (preq && preq.payload)
				{
					run_sheets.push({
						view: sheet,
						req: preq
					});
				}
			}
			
			me.irpt._exec_rpt(run_sheets);
		}
		
		me._directFilter = null;
		
		me.validateFilter = false;
	},
	
	removeObj: function() {
	},
	
	validateItems: function(runall, isloading) {
		var me = this,
			sop = me.sheetoption.model,
			run = !isloading && (me.btabrun || runall);
			
		if (sop && sop.docid)
		{
			if (sop.rptoption && sop.rptoption.uid)
			{
				if (!me.irpt)
				{
					me.validated = true;
					
					var maintab = me.contentarea,
						container = me.owner.dockdiv ? $("<div class='report_container'></div>").appendTo(maintab) : null,
						rlogic = me.owner.dockdiv ? $("<div style='display:none;'></div>").appendTo(container) : [];
					
					if (me.__dx != true)
					{
						me.irpt = new IG$.ReportView({
							instance: me.instance,
							uid: sop.rptoption.uid,
							header: false,
							hiddenstatusbar: true,
							hiddentoolbar: true,
							border: 0,
							vmode: 1,
							frameHeader: false,
							cmode: 1,
							dockdiv_container: container,
							cvmode: me.cvmode,
							auxfilter: me._directFilter,
							width: me._cw,
							height: me._ch,
							renderTo: rlogic[0] || me.contentarea[0],
							_par: me.owner
						});
						
						if (run || isloading)
						{
							me.irpt.on("_lc0", function() {
								me.irpt.un("_lc0");
								
								if (isloading)
								{
									me.container.trigger("i_ready");
								}
								
								if (run)
								{
									me.validateFilter = true;
									me.executeItem();
								}
							});
						}
						
						me._directFilter = null;
						me.validateFilter = false;
					}
				}
				else
				{
					me.container.trigger("i_ready");
				}
				
				if (me.irpt)
				{
					if (me.irpt.uid != sop.rptoption.uid)
					{
						me.irpt.uid = sop.rptoption.uid;
						me.irpt.init_f();
					}
					else if (!isloading && me.irpt.__loaded)
					{
						me.irpt.init_f();
					}
					me.validateFilter = false;
				}
			}
		}
	},
	
	setSize: function(w, h, force) {
		var me = this,
			c = me.contentarea;
			
		me.pw = me.pw || 0;
		me.ph = me.ph || 0;
		
		me._cw = w;
		me._ch = h;
		
		if (me.irpt && me.irpt.dzone && (force || (Math.abs(me.pw - w) > 5 || Math.abs(me.ph - h) > 5)))
		{
			me.pw = w;
			me.ph = h;
			IG$.j$ext._w(c, w);
			IG$.j$ext._h(c, h);
			
			if (me.irpt)
			{
				me.irpt.setSize(w, h);
				
				if (force && !me.irpt.dzone.sizeapplied)
				{
					me.irpt.dzone.updateDisplay(true);
				}
			}
		}
	},
	
	updateFilterContent: function(finfo) {
	}
};