IG$.cVis.networkdiagram = $s.extend(IG$.cVis._echart, {
	subtype: "networkdiagram",
	draw: function(mresult) {
		var i,
			j,
			me = this,
			mcr = me.sheetoption ? me.sheetoption.model.chart_option : null,
			data = mresult._tabledata,
			fc = mresult.colfix,
			fr = mresult.rowfix,
			tc = (data.length > 0) ? data[0].length : 0,
			title,
			fields = [],
			matrixdata = [],
			row,
			tn,
			relationgroups = mcr.relationgroups;

		var me = this,
			cop = me.chart_option,
			rel_range1 = (cop.rel_range1 == IG$.UNDEFINED || cop.rel_range1 == null) ? -1 : cop.rel_range1,
			rel_range2 = (cop.rel_range2 == IG$.UNDEFINED || cop.rel_range2 == null) ? 1 : cop.rel_range2;

		var graph = me.getRelData(mresult, (me.subtype == "networkdiagram_pos") ? 1 : 0, false, relationgroups, {s: rel_range1, t: rel_range2});

		var option = {
			legend: [
				{
					data: graph.categories ? graph.categories.map(function (a) {
						return a.name;
					}) : null
				}
			],
			tooltip: {},
			animationDurationUpdate: 1500,
			animationEasingUpdate: 'quinticInOut',
			series: [
				{
					type: 'graph',
					layout: 'circular',
					circular: {
						rotateLabel: true
					},
					data: graph.nodes,
					links: graph.links,
					categories: graph.categories,
					roam: true,
					label: {
						show: true,
						position: 'right',
						formatter: '{b}'
					},
					lineStyle: {
						color: 'source',
						curveness: 0.3
					}
				}
			]
		};

		me.adjOption(option);

		me.drawmode = "echart";
		
		me.render([option], mresult);

		return [option];
	}
});

IG$.cVis.networkdiagram_pos = $s.extend(IG$.cVis.networkdiagram, {
	subtype: "networkdiagram_pos"
});

IG$.cVis.networkdiagram_neg = $s.extend(IG$.cVis.networkdiagram, {
	subtype: "networkdiagram_neg"
});